const set=Object.assign({level:'toeic',listenMode:'practice',speed:'normal',vocabCount:10},JSON.parse(localStorage.getItem(D)||'{}'));const saveSet=()=>localStorage.setItem(D,JSON.stringify(set));
const pools={highschool:'achieve adapt benefit challenge compare decide effort focus increase method observe prefer protect require result',toeic:'agenda budget client contract deadline delegate invoice negotiate policy revenue schedule strategy supplier',ielts:'allocate alleviate assess coherent derive empirical fluctuate hypothesis inevitable methodology paradigm plausible sustainable',toefl:'abate aberration accommodate advocate ambiguous arduous catalyst comprehensive delineate disseminate efficacy elicit feasible mitigate pervasive pragmatic rigorous'.split(' ')};Object.keys(pools).forEach(k=>{if(typeof pools[k]==='string')pools[k]=pools[k].split(' ')});
const info={agenda:['n.','a list of topics for a meeting','議程','Please read the <mark>agenda</mark> before the meeting.'],budget:['n.','a plan for spending money','預算','The team approved the annual <mark>budget</mark>.'],coherent:['adj.','logical and clear','連貫的','Her explanation was <mark>coherent</mark>.'],rigorous:['adj.','very thorough and careful','嚴謹的','The experiment used <mark>rigorous</mark> methods.'],achieve:['v.','to successfully reach a goal','達成','She worked hard to <mark>achieve</mark> her goal.']};
const q=()=>new Date().toISOString().slice(0,10), fallbackData=()=>({version:1,settings:{},days:{},mistakes:[],learned_words:[],stats:{answers:0,correct:0,study_dates:[]},pet:{mood:65,food:0,chat:[]}}),api=(u,b)=>fetch(u,{method:b?'POST':'GET',headers:{'Content-Type':'application/json'},body:b&&JSON.stringify(b)}).then(r=>r.ok?r.json():Promise.reject(new Error(`HTTP ${r.status}`))).catch(()=>u==='/api/data'?fallbackData():({error:'Local service unavailable'})), save=()=>api('/api/data',data),say=s=>{let e=$('#toast');if(!e)return;e.textContent=s;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2200)},day=()=>{if(!data||!data.days)data=fallbackData();return data.days[q()]||(data.days[q()]={words:[],readingDone:false,listeningDone:false,wordDone:false,vocabDone:false,reviewDone:false,streak:0})};
function wi(w){let a=info[w]||['n./v.','an academic English word','核心英語字彙',`Use <mark>${w}</mark> accurately in a sentence.`];return {w,ipa:`/${w.replace(/[aeiou]/g,'ə')}/`,pos:a[0],en:a[1],zh:a[2],ex:a[3]}}
