function rec(ok,m){let d=day(),s=data.stats;s.answers++;if(ok){s.correct++;d.streak=(d.streak||0)+1;pet('good')}else{d.streak=0;pet('soft');if(m&&!data.mistakes.some(x=>x.id===m.id))data.mistakes.push(m)}if(m){api('/api/history').then(h=>{h.questions=Array.from(new Set([...(h.questions||[]),m.id])).slice(-50);api('/api/history',h)})}if(!s.study_dates.includes(q()))s.study_dates.push(q());save()}
function pet(type){let p=data.pet||(data.pet={mood:65,food:0,chat:[]}),e=$('#petFace');if(!e)return;p.mood=Math.max(0,Math.min(100,p.mood+(type==='good'?2:type==='soft'?-1:1)));e.classList.remove('jump','sad');void e.offsetWidth;e.classList.add(type==='soft'?'sad':'jump');$('#petBubble').textContent=type==='good'?'太棒了！尾巴搖成螺旋槳！':type==='soft'?'沒關係，我陪你再試一次。':'嘿！摸摸收到！';save()}
function taskProgress(){let d=day();return ['readingDone','listeningDone','wordDone','vocabDone','reviewDone'].filter(x=>d[x]).length}
