function home(){let d=day(),p=taskProgress()*20;if(taskProgress()===5&&!d.foodAward){d.foodAward=true;data.pet.food++;save()}return `<section class="card hero"><div><p class="quote">Small steps, bright results.</p><h1>今天也和 Foxy 一起升級吧！</h1><p>完成五個任務可獲得 1 份飼料。飼料：${data.pet.food}（雙擊 Foxy 餵食）</p><div class="progress"><b style="width:${p}%"></b></div><p class="small">今日完成度 ${p}%　連擊 ${d.streak||0}</p></div><div class="mascot">🦊</div></section><section class="card"><h2>今日任務</h2>${[['reading','📖 閱讀',d.readingDone],['listening','🎧 多益聽力 20 題',d.listeningDone],['words','🌱 每日單字',d.wordDone],['vocab','🧠 單字選擇題',d.vocabDone],['review','🔁 錯題複習',d.reviewDone]].map(x=>`<div class="task"><b>${x[1]} ${x[2]?'<span class="tag">完成</span>':''}</b><button data-go="${x[0]}">開始</button></div>`).join('')}</section>`}
const passage=`Cities increasingly use public libraries as more than places to borrow books. In some neighborhoods, libraries offer workshops, quiet study areas, and assistance with online forms. Although critics question whether libraries can meet so many needs, supporters argue that these services make information more accessible. The library's value, they say, lies not only in its collection but also in the opportunities it creates for people to learn and participate.`;
function reading(){return `<section class="card"><div class="row"><h2 class="grow">📖 閱讀（${label()}）</h2><button id="readSpeak">🔊 朗讀</button></div><p class="passage">${passage}</p></section><section class="card"><h3>What is the main idea?</h3>${opts(['Libraries should stop lending books.','Modern libraries provide several community learning services.','Online forms are difficult to use.','Critics manage public libraries.'],1,'The passage explains the expanded community role of libraries.','read-main')}</section>`}
function makeListen(){let a=[];for(let i=1;i<=4;i++)a.push({part:'Part 1 · 看圖描述',audio:`A woman is arranging documents on a desk beside a window.`,stem:'Which statement best describes the picture?',o:['A woman is organizing papers at a desk.','A woman is boarding a train.','A woman is serving lunch.','A woman is repairing a window.'],ans:0,why:'The description mentions arranging documents at a desk.'});for(let i=1;i<=6;i++)a.push({part:'Part 2 · 應答問題',audio:i%2?'When will the marketing report be ready?':'Could you send me the revised contract?',stem:'Choose the best response.',o:i%2?['By Friday afternoon.','At the marketing office.','Yes, it was expensive.']:['Certainly, I will email it today.','The contract was on the desk.','No, the weather is clear.'],ans:0,why:'Choose the response that directly and logically answers the question.'});for(let g=1;g<=2;g++){let audio=`Woman: Have you reserved the conference room for Thursday? Man: Not yet, but I can do it before lunch. Woman: Great. Please invite the sales team as well.`;for(let z=0;z<3;z++)a.push({part:'Part 3 · 短對話',audio,stem:['What does the man promise to do?','When will he do it?','Who should be invited?'][z],o:[['Reserve the conference room','Write a report','Order lunch','Cancel a meeting'],['Before lunch','Thursday evening','Next week','Immediately after dinner'],['The sales team','Only the woman','New clients','The accounting team']][z],ans:0,why:'The answer is stated directly in the dialogue.'})}for(let i=0;i<4;i++)a.push({part:'Part 4 · 簡短獨白',audio:'Good morning, passengers. Flight 208 to Singapore will depart from Gate 14 at 10:30. Please have your boarding pass ready. Passengers needing assistance may speak to a gate agent.',stem:['Where is the flight going?','Which gate should passengers use?','What time will it depart?','Who can passengers ask for help?'][i],o:[['Singapore','Seoul','Sydney','Seattle'],['Gate 14','Gate 4','Gate 40','Gate 24'],['10:30','9:30','11:00','12:30'],['A gate agent','The pilot','A taxi driver','The cashier']][i],ans:0,why:'This information is clearly announced.'});return a}
function listening(){let d=day();if(!d.listening)d.listening=makeListen();let x=d.listening[d.listenAt||0];if(!x){d.listeningDone=true;save();return `<section class="card"><h2>🎉 聽力 20 題完成！</h2><p>Foxy 給你一份飼料！</p></section>`}return `<section class="card"><div class="row"><h2 class="grow">🎧 ${x.part}</h2><span class="tag">${(d.listenAt||0)+1} / 20</span></div><button id="playListen">▶ 播放英文</button><p class="small">${set.listenMode==='exam'?'模考模式：每題只能播放一次。':'練習模式：可重播。'}　語速：${set.speed}</p><h3>${x.stem}</h3>${opts(x.o,x.ans,x.why,'listen-'+(d.listenAt||0))}</section>`}
function opts(o,a,why,id){return o.map((x,i)=>`<button class="option answer" data-id="${id}" data-ok="${i===a}" data-why="${why}">${'ABCD'[i]||i+1}. ${x}</button>`).join('')+`<div class="feedback" hidden></div>`}
function words(){let d=day(),pool=pools[set.level];if(!d.words.length){d.words=pool.slice().sort(()=>Math.random()-.5).slice(0,15+new Date().getDate()%6);data.learned_words.push(...d.words.filter(x=>!data.learned_words.includes(x)));save()}return `<section class="card"><h2>🌱 ${label()}每日新詞</h2>${d.words.map(w=>{let x=wi(w);return `<article class="word"><h3>${w}</h3><span class="ipa">${x.ipa}</span><button class="wordSpeak" data-w="${w}">🔊</button><p><b>${x.pos}</b> · ${x.en}<br>${x.zh}</p><p>${x.ex}</p></article>`}).join('')}<button id="finishWords">我已瀏覽今天的單字</button></section>`}
function vocab(){let d=day(),n=set.vocabCount;if(!d.vocab)d.vocab=Array.from({length:n},(_,i)=>{let pool=pools[set.level],w=pool[i%pool.length],x=wi(w),type=i%4,others=pool.filter(z=>z!==w).slice(1,4),o=type===0?[w,...others].sort(()=>Math.random()-.5).map(z=>z===w?x.zh:wi(z).zh):[w,...others].sort(()=>Math.random()-.5);return {w,type,o,ans:type===0?x.zh:w,x}});let z=d.vocab[d.vocabAt||0];if(!z){d.vocabDone=true;save();return `<section class="card"><h2>🎉 單字測驗完成</h2></section>`}let stems=[`「${z.w}」最接近哪個中文意思？`,`「${z.x.zh}」對應哪個英文單字？`,`Complete: Please use _____ accurately in a sentence.`,`Which word is most closely related to this academic term?`];return `<section class="card"><h2>🧠 單字測驗 <span class="tag">${(d.vocabAt||0)+1}/${n}</span></h2><h3>${stems[z.type]}</h3>${opts(z.o,z.o.indexOf(z.ans),`${z.x.ipa} · ${z.x.pos}<br>${z.x.ex}`,'vocab-'+(d.vocabAt||0))}</section>`}
function review(){let m=data.mistakes.filter(x=>x.hits<2);if(!m.length)return `<section class="card"><h2>🎉 錯題本很乾淨</h2></section>`;let x=m[0],o=x.options.slice().sort(()=>Math.random()-.5);return `<section class="card"><h2>🔁 錯題複習</h2><p>${x.q}</p>${o.map(v=>`<button class="option review" data-id="${x.id}" data-v="${v}">${v}</button>`).join('')}<div class="feedback" hidden></div></section>`}
function stats(){let s=data.stats,r=s.answers?Math.round(s.correct/s.answers*100):0;return `<section class="card"><h2>📊 統計</h2><div class="grid"><div class="metric"><b>${s.study_dates.length}</b>學習天數</div><div class="metric"><b>${s.answers}</b>答題數</div><div class="metric"><b>${r}%</b>正確率</div></div></section><section class="card"><h3>Obsidian 匯出</h3><button id="export">下載 Markdown</button></section>`}
function settings(){return `<section class="card"><h2>⚙️ 學習設定</h2><label>全域難度<select id="level" class="input">${[['highschool','高中程度'],['toeic','多益程度'],['ielts','雅思程度'],['toefl','托福程度']].map(x=>`<option value="${x[0]}">${x[1]}</option>`).join('')}</select></label><label>聽力模式<select id="listenMode" class="input"><option value="practice">練習模式（可重播）</option><option value="exam">模考模式（只能聽一次）</option></select></label><label>朗讀語速<select id="speed" class="input"><option value="slow">慢</option><option value="normal">正常</option><option value="fast">快</option></select></label><label>單字測驗題數<select id="vocabCount" class="input"><option>10</option><option>20</option><option>30</option></select></label><button id="saveSettings">儲存學習設定</button></section><section class="card"><h3>API Key 狀態</h3>${Object.entries(config.providers).map(([n,p])=>`<p>${p.key?'🟢':'⚪'} ${n}　模型：${p.model}</p>`).join('')}<p class="small">優先順序：${config.order.join(' → ')}。Key 請在既有設定欄位以 config.json 管理。</p><button id="export2">匯出錯題與生詞</button></section>`}
function label(){return {highschool:'高中',toeic:'多益',ielts:'雅思',toefl:'托福'}[set.level]}
function bind(){document.querySelectorAll('.answer').forEach(b=>b.onclick=()=>{let ok=b.dataset.ok==='true',f=b.parentElement.querySelector('.feedback'),kind=b.dataset.id.split('-')[0];if(b.parentElement.dataset.done)return;b.parentElement.dataset.done=1;b.classList.add(ok?'right':'wrong');f.hidden=false;f.innerHTML=(ok?'✅ 正確！':'❌ 再試一次。')+b.dataset.why;let o=[...b.parentElement.querySelectorAll('.answer')].map(x=>x.textContent.replace(/^[A-D0-9]+\. /,'')),ans=[...b.parentElement.querySelectorAll('.answer')].find(x=>x.dataset.ok==='true').textContent.replace(/^[A-D0-9]+\. /,'');rec(ok,{id:b.dataset.id,q:b.parentElement.querySelector('h3').textContent,options:o,answer:ans,hits:0});if(kind==='listen')day().listenAt=(day().listenAt||0)+1;if(kind==='vocab')day().vocabAt=(day().vocabAt||0)+1;save();setTimeout(render,850)});if(tab==='reading')$('#readSpeak').onclick=()=>speech(passage);if(tab==='listening')$('#playListen').onclick=()=>{let d=day(),x=d.listening[d.listenAt||0];if(set.listenMode==='exam'&&x.played){say('模考模式只能聽一次。');return}x.played=true;save();speech(x.audio)};if(tab==='words'){document.querySelectorAll('.wordSpeak').forEach(x=>x.onclick=()=>speech(x.dataset.w));$('#finishWords').onclick=()=>{day().wordDone=true;save();pet('good');say('新詞任務完成！')}}if(tab==='review')document.querySelectorAll('.review').forEach(b=>b.onclick=()=>{let x=data.mistakes.find(z=>z.id===b.dataset.id),ok=b.dataset.v===x.answer;x.hits+=ok?1:0;rec(ok);day().reviewDone=true;save();say(ok?'答對！':'答案是 '+x.answer);setTimeout(render,700)});if(tab==='settings'){['level','listenMode','speed','vocabCount'].forEach(k=>{$('#'+k).value=set[k]});$('#saveSettings').onclick=()=>{['level','listenMode','speed'].forEach(k=>set[k]=$('#'+k).value);set.vocabCount=+$('#vocabCount').value;saveSet();say('設定已儲存');render()};$('#export2').onclick=exportMd}if(tab==='stats')$('#export').onclick=exportMd}
function exportMd(){let m=data.mistakes.filter(x=>x.hits<2),ws=[...new Set(data.learned_words)].map(wi),md=`# Bright English 匯出\n\n## 待複習錯題\n${m.map(x=>`- [ ] ${x.q}\n  - 答案：${x.answer}`).join('\n')||'無'}\n\n## 生詞\n| Word | 中文 | English |\n|---|---|---|\n${ws.map(x=>`|${x.w}|${x.zh}|${x.en}|`).join('\n')}`;let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([md]));a.download=`Bright-English-${q()}.md`;a.click()}
const localReplies=['你今天已經比昨天更靠近目標了！','這個字先放進一句自己的句子，記得最快。','休息 30 秒也可以，回來我還在。','答錯是地圖，不是扣分單。','試著先抓關鍵字，再推整句意思。','Foxy 認證：你有認真學習的光！'];function fallback(t){let w=day().words.slice(0,3).join('、');if(/單字|word/i.test(t))return `今天的單字有 ${w}。挑一個，我陪你造句！`;if(/文法|grammar/i.test(t))return '把句子貼給我吧；先找主詞和動詞，是很好的第一步。';return localReplies[Math.floor(Math.random()*localReplies.length)]}
function initPet(){let p=data.pet||(data.pet={mood:65,food:0,chat:[]});$('#pet').onclick=()=>{$('#chat').hidden=false;showChat()};$('#closeChat').onclick=()=>$('#chat').hidden=true;$('#sendChat').onclick=sendChat;$('#chatText').onkeydown=e=>{if(e.key==='Enter')sendChat()};$('#petFace').ondblclick=e=>{e.stopPropagation();if(p.food>0){p.food--;p.mood=Math.min(100,p.mood+12);say('Foxy 吃得好開心！');save()}else say('完成五項今日任務可獲得飼料！')}}function showChat(){let log=$('#chatLog'),p=data.pet;log.innerHTML=(p.chat||[]).map(x=>`<p class="${x.role}"><b>${x.role==='user'?'你':'Foxy'}：</b>${x.content}</p>`).join('')||'<p class="assistant">Foxy：嗨！今天想練單字、文法，還是想聊聊？</p>';log.scrollTop=log.scrollHeight}
async function sendChat(){let input=$('#chatText'),text=input.value.trim();if(!text)return;input.value='';let p=data.pet;p.chat.push({role:'user',content:text});showChat();let mood=p.mood>70?'熱情又俏皮':p.mood<35?'有點撒嬌但溫柔':'溫暖幽默';let words=day().words.join(', ');let sys=`You are Foxy, a ${mood} fox English study companion. Help with English learning, occasionally make gentle jokes, never shame the learner. Today's words: ${words}. Reply in Traditional Chinese with helpful English examples when useful; keep under 120 Chinese characters.`;let r=await api('/api/chat',{messages:[{role:'system',content:sys},...p.chat.slice(-10)]});p.chat.push({role:'assistant',content:r.reply||fallback(text)});p.chat=p.chat.slice(-20);save();showChat()}
(async()=>{try{data=await api('/api/data');if(!data||!data.days)data=fallbackData();config=await api('/api/config');if(!config||!config.providers)config={providers:{},order:[]};data.pet||={mood:65,food:0,chat:[]};api('/api/history').then(h=>data.history=h.questions||[]);render();initPet()}catch(e){data=fallbackData();config={providers:{},order:[]};render();say('Offline fallback mode is active.')}})();

