const zhMap={achieve:'達成',adapt:'適應',benefit:'益處',challenge:'挑戰',compare:'比較',decide:'決定',effort:'努力',focus:'焦點',increase:'增加',method:'方法',observe:'觀察',prefer:'偏好',protect:'保護',require:'需要',result:'結果',agenda:'議程',budget:'預算',client:'客戶',contract:'合約',deadline:'截止期限',delegate:'委派',invoice:'發票',negotiate:'談判',policy:'政策',revenue:'營收',schedule:'時程',strategy:'策略',supplier:'供應商',allocate:'分配',alleviate:'減輕',assess:'評估',coherent:'連貫的',derive:'源自',empirical:'實證的',fluctuate:'波動',hypothesis:'假設',inevitable:'不可避免的',methodology:'研究方法',paradigm:'典範',plausible:'合理可信的',sustainable:'永續的',abate:'減弱',aberration:'異常',accommodate:'容納；適應',advocate:'提倡',ambiguous:'模稜兩可的',arduous:'艱鉅的',catalyst:'催化劑',comprehensive:'全面的',delineate:'描繪；界定',disseminate:'傳播',efficacy:'功效',elicit:'引出',feasible:'可行的',mitigate:'減輕',pervasive:'普遍存在的',pragmatic:'務實的',rigorous:'嚴謹的'};
const contextExamples={agenda:'Before the quarterly meeting, the manager emailed everyone the agenda so they could prepare each discussion topic.',budget:'Because sales were lower than expected, the department reduced its travel budget for the rest of the year.',client:'The consultant called the client to clarify which services the company needed before writing a proposal.',contract:'Both companies signed the contract after their lawyers agreed on the payment and delivery terms.',deadline:'To finish the report before Friday’s deadline, Mia stayed late to check every chart.',invoice:'The accounting team could not release payment until the supplier sent an invoice with the correct amount.',negotiate:'The buyer tried to negotiate a lower price by promising to order a larger quantity next year.',revenue:'Online subscriptions increased the company’s revenue even though its store sales remained unchanged.',strategy:'Our marketing strategy focuses on reaching first-time customers through short instructional videos.',supplier:'When the usual supplier delayed the shipment, the factory contacted another company for materials.',hypothesis:'The scientist tested her hypothesis that plants grow faster when their roots receive more oxygen.',empirical:'The claim became convincing only after researchers collected empirical evidence from several experiments.',fluctuate:'Oil prices tend to fluctuate when international events make investors uncertain about future supply.',methodology:'The article explains its methodology, including how participants were selected and how results were measured.',sustainable:'The city installed solar panels because renewable energy is more sustainable than burning fossil fuels.',ambiguous:'The instruction was ambiguous, so different employees completed the form in different ways.',arduous:'After an arduous six-hour hike over steep rocks, the group finally reached the mountain shelter.',catalyst:'The new discovery acted as a catalyst for further research by making a difficult experiment possible.',delineate:'The map clearly delineates the boundary between the protected forest and the nearby farmland.',disseminate:'The health department used social media to disseminate safety information quickly during the storm.',efficacy:'Doctors studied the vaccine’s efficacy by comparing infection rates in treated and untreated groups.',mitigate:'Planting trees can mitigate summer heat because shade lowers the temperature around buildings.',pervasive:'Smartphones are so pervasive that many people now use them for banking, travel, and work.',pragmatic:'Rather than waiting for a perfect solution, the team chose a pragmatic plan they could afford now.',rigorous:'The journal accepted the study only after a rigorous review checked its methods and evidence.'};
const vocabGenerationPrompt=`For every vocabulary fill-in-the-blank item: use a sentence of at least 12 words with at least two independent context clues (collocation, cause/effect, contrast, definition, or synonym). Never use “Please use _____ in a sentence”, “The word _____”, or “fill in the blank”. Test each distractor mentally; if another option also fits naturally, discard the item. Fill-in items must be 30% or less of the set.`;
function wi(w){let base=info[w]||[],zh=zhMap[w]||'待補充釋義';return {w,ipa:base[0]?`/${w.replace(/[aeiou]/g,'ə')}/`:`/${w}/`,pos:base[0]||'n./v.',en:base[1]||`a useful English word: ${w}`,zh,ex:base[3]||`Use <mark>${w}</mark> accurately in a complete sentence.`}}
function validMeaning(x){return !!x&&x.length>=2&&!/核心|高頻|學術字彙|n\.|v\.|adj\./i.test(x)}
function validQuestion(x){let o=x&&x.o;return !!(x&&x.stem&&Array.isArray(o)&&o.length>=3&&o.every(a=>String(a).trim())&&new Set(o).size===o.length&&Number.isInteger(x.ans)&&o[x.ans])}
function validBlank(sentence,choices){let lower=String(sentence||'').toLowerCase(),words=lower.match(/[a-z]+|_____/g)||[],bad=/please\s+use\s+_____|the\s+word\s+_____|fill\s+in\s+the\s+blank/;if(bad.test(lower)||words.length<12)return false;let pos=words.indexOf('_____'),near=words.slice(Math.max(0,pos-3),pos+4).filter(w=>!['the','a','an','to','in','on','at','for','of','and','or','please','with'].includes(w));return pos>=0&&near.length>=2&&new Set(choices).size===choices.length}
function questionHash(s){let h=0;for(const c of String(s))h=((h<<5)-h+c.charCodeAt(0))|0;return (h>>>0).toString(16)}
function historyAdd(stems,topic){api('/api/history').then(h=>{h.questions=[...(h.questions||[]),...stems.map(questionHash)].slice(-100);h.topics=[...(h.topics||[]),topic].filter(Boolean).slice(-20);api('/api/history',h)})}
function food(amount,reason){let d=day(),p=data.pet||(data.pet={mood:65,food:0,chat:[]});d.foodToday=d.foodToday||0;let give=Math.max(0,Math.min(amount,10-d.foodToday));if(give){d.foodToday+=give;p.food+=give;say(`+${give} food: ${reason} (${d.foodToday}/10 today)`);save()} }
function rec(ok,m){let d=day(),s=data.stats;s.answers++;if(ok){s.correct++;d.streak=(d.streak||0)+1;d.correctForFood=(d.correctForFood||0)+1;pet('good');if(d.correctForFood%5===0)food(1,'five correct answers')}else{d.streak=0;pet('soft');if(m&&!data.mistakes.some(x=>x.id===m.id))data.mistakes.push(m)}if(m)historyAdd([m.q],m.id.split('-')[0]);if(!s.study_dates.includes(q()))s.study_dates.push(q());save()}
function awardTask(key,label){let d=day();if(!d.foodTasks)d.foodTasks={};if(!d.foodTasks[key]){d.foodTasks[key]=true;food(1,`${label} completed`)}}
function readSet(){return [{topic:'community libraries',passage:'Public libraries now offer more than books. Many provide quiet workspaces, digital-skills workshops, and help with online services. Supporters argue that these programs make reliable information easier to reach. Critics note that resources are limited, but librarians say partnerships with local groups allow services to grow.',qs:[['What is the main idea?',['Libraries should only lend printed books.','Libraries provide several community learning services.','Online services are replacing libraries.','Librarians oppose partnerships.'],1],['What concern do critics have?',['Programs are too easy.','Resources are limited.','Books are unreliable.','Workshops are private.'],1],['The word “reliable” is closest in meaning to',['trustworthy','expensive','unusual','temporary'],0],['What can be inferred about partnerships?',['They can help libraries expand services.','They eliminate all costs.','They replace librarians.','They are not local.'],0]]},{topic:'urban transport',passage:'Several cities are testing electric buses on crowded routes. The vehicles cost more initially than diesel buses, yet they use less energy over time and produce no exhaust at the street level. Transit planners are studying charging schedules carefully because a bus that cannot recharge on time may disrupt an entire route.',qs:[['Why are cities testing electric buses?',['They need no planning.','They may reduce energy use and street-level emissions.','They are always cheaper to buy.','They can travel without charging.'],1],['What problem concerns planners?',['Bus color','Charging delays','Ticket design','Road width'],1],['The word “disrupt” is closest in meaning to',['interrupt','improve','measure','replace'],0],['What does the passage suggest?',['Initial price is the only cost.','Charging management is important for service.','Diesel buses have no emissions.','All cities have adopted electric buses.'],1]]},{topic:'scientific research',passage:'Researchers studying sleep often ask volunteers to keep daily diaries instead of relying only on memory at the end of a week. Diaries can reveal patterns between sleep, work, and mood. However, they also depend on participants recording information consistently. For this reason, scientists compare diary entries with data from wearable devices when possible.',qs:[['Why do researchers use daily diaries?',['To avoid studying mood.','To identify patterns more accurately.','To replace wearable devices.','To shorten the study.'],1],['What is one limitation of diaries?',['They cannot contain dates.','They depend on consistent recording.','They are too expensive.','They measure only work.'],1],['The word “reveal” is closest in meaning to',['hide','show','repeat','reduce'],1],['Why compare diaries with wearable data?',['To check information from another source.','To make diaries longer.','To remove volunteers.','To study only devices.'],0]]}].map(r=>({topic:r.topic,passage:r.passage,questions:r.qs.map(a=>({stem:a[0],o:a[1],ans:a[2],why:'The correct option is supported by the passage; the other options add an unsupported or contradictory claim.'}))}))}
function reading(){let d=day();if(!Array.isArray(d.readings)||d.readings.length<3){let hist=data.history||[];d.readings=readSet().filter(r=>!hist.includes(questionHash(r.questions[0].stem)));if(!d.readings.length){d.readingExhausted=true;return `<section class="card"><h2>Today’s new reading questions are used up.</h2><p>Use review mode, or choose AI fresh set when a provider key is available.</p><button id="freshReading">Generate fresh AI set</button></section>`}d.readings.forEach(r=>historyAdd(r.questions.map(x=>x.stem),r.topic));save()}let qs=d.readings.flatMap((r,ri)=>r.questions.map((x,qi)=>({...x,ri,qi,passage:r.passage,topic:r.topic})));return `<section class="card"><div class="row"><h2 class="grow">Reading: ${qs.length} questions / 3 passages</h2><button id="freshReading">Generate fresh AI set</button></div><p class="small">New topics are checked against the recent history. No repeated fallback questions are injected.</p>${d.readings.map((r,ri)=>`<article class="word"><div class="row"><h3 class="grow">Passage ${ri+1}: ${r.topic}</h3><button class="readPassage" data-ri="${ri}">Play</button></div><p class="passage">${r.passage}</p>${r.questions.map((x,qi)=>`<div class="readQ"><h3>${qi+1}. ${x.stem}</h3>${x.o.map((o,i)=>`<button class="option groupedAnswer" data-type="reading" data-ri="${ri}" data-qi="${qi}" data-ok="${i===x.ans}" data-why="${x.why}">${'ABCD'[i]}. ${o}</button>`).join('')}<div class="feedback" hidden></div></div>`).join('')}</article>`).join('')}</section>`}
async function freshReading(){let h=await api('/api/history'),recent=(h.questions||[]).slice(-100),topics=(h.topics||[]).slice(-20);let prompt=`Create exactly 3 authentic TOEIC/IELTS/TOEFL reading passages, each 200-350 words and 4 multiple-choice questions. Return JSON {readings:[{topic,passage,questions:[{stem,o:[four unique options],ans:0,why}]}]}. Avoid these recent stem hashes: ${recent.join(',')}. Avoid these topics: ${topics.join(',')}. Do not write trivia, generic labels, or meaningless questions.`;for(let retry=0;retry<3;retry++){let r=await api('/api/generate',{prompt});let rs=r.result&&r.result.readings;if(!r.error&&Array.isArray(rs)&&rs.length>=3&&rs.every(x=>x.questions&&x.questions.every(validQuestion))){let hashes=rs.flatMap(x=>x.questions.map(y=>questionHash(y.stem)));if(!hashes.some(x=>recent.includes(x))){day().readings=rs.slice(0,3);day().readingExhausted=false;rs.forEach(x=>historyAdd(x.questions.map(y=>y.stem),x.topic));save();say(`Fresh set generated by ${r.provider}`);render();return}}}say('AI did not return a valid new set; no repeated questions were used.')}
function listening(){let d=day();if(!d.listening||d.listening.some(x=>!validQuestion(x)))d.listening=makeListen();let start=d.listenAt||0,x=d.listening[start];if(!x){d.listeningDone=true;awardTask('listening','listening');save();return `<section class="card"><h2>Listening complete</h2></section>`}let grouped=x.audio.includes('Woman:')||x.audio.startsWith('Good morning');let group=grouped?d.listening.slice(start).filter(y=>y.audio===x.audio):[x];return `<section class="card"><div class="row"><h2 class="grow">Listening: ${x.part}</h2><span class="tag">${start+1}–${start+group.length} / 20</span></div><button id="playListen">Play audio</button><p class="small">${set.listenMode==='exam'?'Exam mode: one playback only.':'Practice mode: replay allowed.'} All questions are visible before playback.</p>${group.map((z,n)=>`<div class="listenQ"><h3>${n+1}. ${z.stem}</h3>${z.o.map((o,i)=>`<button class="option groupedAnswer" data-type="listening" data-index="${start+n}" data-ok="${i===z.ans}" data-why="${z.why}">${'ABCD'[i]}. ${o}</button>`).join('')}<div class="feedback" hidden></div></div>`).join('')}</section>`}
function vocab(){let d=day(),n=set.vocabCount;if(!d.vocab||d.vocab.some(z=>!validMeaning(z.x&&z.x.zh)||new Set(z.o||[]).size!==z.o.length||(z.type===2&&!validBlank(z.sentence,z.o)))){buildValidatedVocab()}let z=d.vocab[d.vocabAt||0];if(!z){d.vocabDone=true;save();return `<section class="card"><h2>Vocabulary quiz complete</h2></section>`}let prompt=z.type===0?`What is the Chinese meaning of “${z.w}”?`:z.type===1?`Which English word means “${z.x.zh}”?`:z.type===2?z.sentence:`Which word is most closely related to “${z.w}”?`;let choices=z.type===0?z.o.map(w=>wi(w).zh):z.o;let answer=z.type===0?z.x.zh:z.w;return `<section class="card"><h2>Vocabulary quiz <span class="tag">${(d.vocabAt||0)+1}/${n}</span></h2><h3>${prompt}</h3>${choices.map((o,i)=>`<button class="option vocabAnswer" data-ok="${o===answer}" data-index="${d.vocabAt||0}">${'ABCD'[i]}. ${o}</button>`).join('')}<div class="feedback" hidden></div></section>`}
function buildValidatedVocab(){let d=day(),pool=pools[set.level],n=set.vocabCount,fillable=pool.filter(w=>contextExamples[w]);d.vocab=Array.from({length:n},(_,i)=>{let w=pool[i%pool.length],x=wi(w),others=pool.filter(z=>z!==w).filter(z=>validMeaning(wi(z).zh)).slice(0,3),type=[0,1,0,1,3,2][i%6];if(type===2&&!fillable.includes(w)){w=fillable[i%fillable.length];x=wi(w);others=pool.filter(z=>z!==w).slice(0,3)}let o=[w,...others].sort(()=>Math.random()-.5),sentence=type===2?contextExamples[w].replace(new RegExp(`\\b${w}\\b`,'i'),'_____'):'';if(type===2&&!validBlank(sentence,o))type=0;return {w,type,o,ans:w,x,sentence}});d.vocabAt=0;save()}
function bind(){let fresh=$('#freshReading');if(fresh)fresh.onclick=freshReading;document.querySelectorAll('[data-go]').forEach(x=>x.onclick=()=>{if(x.dataset.go==='vocab'&&!day().vocab)buildValidatedVocab();tab=x.dataset.go;render()});document.querySelectorAll('.readPassage').forEach(b=>b.onclick=()=>speech(day().readings[+b.dataset.ri].passage));document.querySelectorAll('.groupedAnswer').forEach(b=>b.onclick=()=>{let box=b.parentElement;if(box.dataset.done)return;box.dataset.done='1';let ok=b.dataset.ok==='true';b.classList.add(ok?'right':'wrong');let f=box.querySelector('.feedback');f.hidden=false;f.textContent=(ok?'Correct. ':'Try again. ')+b.dataset.why;let type=b.dataset.type;if(type==='listening'){let i=+b.dataset.index,z=day().listening[i];rec(ok,{id:'listen-'+questionHash(z.stem),q:z.stem,options:z.o,answer:z.o[z.ans],hits:0});let all=[...document.querySelectorAll('.listenQ')].every(x=>x.dataset.done);if(all){day().listenAt=(day().listenAt||0)+document.querySelectorAll('.listenQ').length;setTimeout(render,700)}}else{let ri=+b.dataset.ri,qi=+b.dataset.qi,z=day().readings[ri].questions[qi];rec(ok,{id:'read-'+questionHash(z.stem),q:z.stem,options:z.o,answer:z.o[z.ans],hits:0});let all=[...document.querySelectorAll('.readQ')].every(x=>x.dataset.done);if(all){day().readingDone=true;awardTask('reading','reading')}}save()});document.querySelectorAll('.vocabAnswer').forEach(b=>b.onclick=()=>{let box=b.parentElement;if(box.dataset.done)return;box.dataset.done='1';let i=+b.dataset.index,z=day().vocab[i],ok=b.dataset.ok==='true';b.classList.add(ok?'right':'wrong');let f=box.querySelector('.feedback');f.hidden=false;f.innerHTML=(ok?'Correct. ':'Try again. ')+`${z.x.ipa} · ${z.x.pos}<br>${z.x.ex}`;rec(ok,{id:'vocab-'+questionHash(z.w),q:z.w,options:z.o.map(w=>wi(w).zh),answer:z.x.zh,hits:0});day().vocabAt=i+1;save();setTimeout(render,650)});if(tab==='listening')$('#playListen').onclick=()=>{let d=day(),x=d.listening[d.listenAt||0];if(set.listenMode==='exam'&&x.played)return say('Exam mode allows one playback.');x.played=true;save();speech(x.audio)};if(tab==='words'){document.querySelectorAll('.wordSpeak').forEach(x=>x.onclick=()=>speech(x.dataset.w));let b=$('#finishWords');if(b)b.onclick=()=>{day().wordDone=true;awardTask('words','words');save();say('Words completed.')}}if(tab==='review')document.querySelectorAll('.review').forEach(b=>b.onclick=()=>{let x=data.mistakes.find(z=>z.id===b.dataset.id),ok=b.dataset.v===x.answer;x.hits+=ok?1:0;rec(ok);day().reviewDone=true;awardTask('review','review');save();setTimeout(render,500)});if(tab==='settings'){['level','listenMode','speed','vocabCount'].forEach(k=>{$('#'+k).value=set[k]});$('#saveSettings').onclick=()=>{['level','listenMode','speed'].forEach(k=>set[k]=$('#'+k).value);set.vocabCount=+$('#vocabCount').value;saveSet();say('Settings saved.')}}}

function home(){let d=day(),done=taskProgress(),p=done*20;return `<section class="card hero"><div><p class="quote">Small steps, bright results.</p><h1>Today with Foxy</h1><p>Food earned today: <b>${d.foodToday||0} / 10</b> · Foxy food: <b>${data.pet.food||0}</b></p><div class="progress"><b style="width:${p}%"></b></div><p class="small">Daily completion: ${p}%</p></div><div class="mascot">🦊</div></section><section class="card"><h2>Daily tasks</h2>${[['reading','Reading',d.readingDone],['listening','Listening',d.listeningDone],['words','Daily words',d.wordDone],['vocab','Vocabulary quiz',d.vocabDone],['review','Review',d.reviewDone]].map(x=>`<div class="task"><b>${x[1]} ${x[2]?'<span class="tag">Done</span>':''}</b><button data-go="${x[0]}">Open</button></div>`).join('')}</section>`}

/* Navigation, favourites, news reading, and four-star difficulty upgrade. */
var wordPane='learn';
var reviewCategory='All';
function starMeta(){return {one:{stars:'★',label:'B2 · IELTS 6 / TOEIC 600',pool:'highschool',rate:.82,brief:'university foundation and everyday business vocabulary; short sentences'},two:{stars:'★★',label:'C1 · IELTS 7 / TOEIC 800',pool:'toeic',rate:1,brief:'common business and academic vocabulary; medium sentences'},three:{stars:'★★★',label:'C1+–C2 · IELTS 8 / GMAT 700',pool:'ielts',rate:1.12,brief:'advanced academic and business vocabulary; complex sentences'},four:{stars:'★★★★',label:'C2 · GRE 340 / IELTS 9',pool:'toefl',rate:1.25,brief:'rare, high-level academic and critical-reasoning vocabulary; dense long sentences'}}}
function levelKey(){if(!['one','two','three','four'].includes(set.level))set.level='two';return set.level}
function difficulty(){let m=starMeta(),k=levelKey();return `<select class="difficulty globalLevel"><option value="one" ${k==='one'?'selected':''}>★ Easy — ${m.one.label}</option><option value="two" ${k==='two'?'selected':''}>★★ Medium — ${m.two.label}</option><option value="three" ${k==='three'?'selected':''}>★★★ Hard — ${m.three.label}</option><option value="four" ${k==='four'?'selected':''}>★★★★ Expert — ${m.four.label}</option></select>`}
function proverbToday(){let a=[['Actions speak louder than words.','行動勝於言語。'],['Every cloud has a silver lining.','黑暗中總有一線光明。'],['Practice makes perfect.','熟能生巧。'],['Where there is a will, there is a way.','有志者事竟成。'],['The early bird catches the worm.','早起的鳥兒有蟲吃。'],['Better late than never.','遲做總比不做好。'],['A journey of a thousand miles begins with a single step.','千里之行，始於足下。']];return a[new Date().getDate()%a.length]}
function favoriteStore(){try{return JSON.parse(localStorage.getItem('bright-favorites-v1')||'[]')}catch{return []}}
function saveFavorites(a){localStorage.setItem('bright-favorites-v1',JSON.stringify(a))}
function isFavorite(w){return favoriteStore().some(x=>x.word===w)}
function addFavorite(w){openFavoriteEditor(w)}
function newsForToday(){let samples=[{topic:'Cities expand cool-roof programs',en:'Several cities are expanding programs that encourage owners to paint rooftops with reflective materials. Supporters say cooler roofs can reduce indoor temperatures during heat waves and lower electricity demand. Building managers note that installation costs can be significant, yet researchers argue that savings may grow when programs are combined with tree planting and better insulation.',zh:'多個城市正擴大鼓勵屋主使用反射性屋頂材料的計畫。支持者表示，較涼爽的屋頂可在熱浪期間降低室內溫度與用電需求。建築管理者指出安裝成本可能很高，但研究人員認為，若搭配植樹與改善隔熱，節省效果可能更明顯。'}, {topic:'Libraries lend tools for home repairs',en:'A growing number of public libraries are lending tools alongside books. Residents can borrow drills, sewing machines, and repair kits for short projects. Librarians say the service helps people avoid buying equipment they may use only once. The programs also offer workshops that teach visitors how to use tools safely.',zh:'越來越多公共圖書館除了書籍之外，也開始出借工具。居民可借用電鑽、縫紉機與維修組合包來完成短期專案。圖書館員表示，這項服務可幫助人們避免購買只會使用一次的設備；計畫也提供工作坊，教導訪客如何安全使用工具。'}];return samples[new Date().getDate()%samples.length]}
function newsQuestions(article){if(article.topic.includes('cool-roof'))return [{stem:'What is the main purpose of the article?',o:['To explain how cool-roof programs can reduce heat and energy use.','To advertise paint brands.','To ban trees in cities.','To compare library services.'],ans:0,why:'The article describes reflective roofs and their potential benefits.'},{stem:'What concern do building managers mention?',o:['Installation costs can be significant.','Roofs cannot reflect light.','Trees require no water.','Electricity is free.'],ans:0,why:'The article explicitly notes the cost concern.'},{stem:'The word “significant” is closest in meaning to',o:['important or considerable','invisible','temporary','unrelated'],ans:0,why:'In this context, significant describes a considerable cost.'}];return [{stem:'What is the main purpose of the article?',o:['To describe a library tool-lending program and its benefits.','To argue that books should be replaced.','To compare private companies.','To advertise equipment.'],ans:0,why:'The article explains the program and why communities use it.'},{stem:'Which detail is mentioned in the article?',o:['Residents can borrow equipment for short projects.','Visitors must purchase every tool.','Libraries no longer lend books.','Only professional builders may join.'],ans:0,why:'The article explicitly states that residents may borrow equipment.'},{stem:'What do workshops teach?',o:['How to use tools safely.','How to build libraries.','How to sell equipment.','How to publish books.'],ans:0,why:'The article states that workshops teach safe use.'}]}
function reading(){let d=day(),n=d.news||(d.news=newsForToday());d.newsQuestions=d.newsQuestions||newsQuestions(n);let p=proverbToday();return `<section class="card"><div class="row"><h2 class="grow">今日閱讀 · ${n.topic}</h2>${difficulty()}<button id="newsSpeak">🔊</button><button id="newsAi">AI 新聞</button></div><p class="quote">${p[0]}<br><span class="small">${p[1]}</span></p><h3>English news</h3><p class="passage">${n.en}</p><h3>中文翻譯</h3><p class="translation">${n.zh}</p></section><section class="card"><h2>閱讀測驗</h2><p class="small">題目依上方本文建立。</p>${d.newsQuestions.map((x,i)=>`<div class="articleQ"><h3>${i+1}. ${x.stem}</h3>${x.o.map((o,j)=>`<button class="option articleAnswer" data-i="${i}" data-ok="${j===x.ans}">${'ABCD'[j]}. ${o}</button>`).join('')}<div class="feedback" hidden></div></div>`).join('')}</section>`}
async function freshNews(){let m=starMeta()[levelKey()],prompt=`Create one current-style English news article for an English learner at ${m.label}: ${m.brief}. Return JSON {topic,en,zh,questions:[{stem,o:[four unique options],ans,why}]}. The Chinese translation must be complete Traditional Chinese. Questions (3 to 5) must be based only on the article.`;let r=await api('/api/generate',{prompt});let x=r.result;if(r.error||!x||!x.en||!x.zh||!Array.isArray(x.questions)||x.questions.length<3||!x.questions.every(validQuestion)){say('AI news was unavailable; the local daily article remains.');return}day().news={topic:x.topic||'Daily news',en:x.en,zh:x.zh};day().newsQuestions=x.questions;save();say(`AI news generated by ${r.provider}`);render()}
function listening(){let m=starMeta()[levelKey()],x={audio:'Good morning. The regional sales meeting will begin at nine thirty in the main conference room. Please bring the revised quarterly report and arrive ten minutes early.',qs:[['Where will the meeting take place?',['In the main conference room','At a restaurant','In the lobby','Online'],0],['What should attendees bring?',['The revised quarterly report','A travel ticket','Lunch','A new computer'],0],['When should attendees arrive?',['Ten minutes early','At noon','After lunch','Tomorrow'],0]]};return `<section class="card"><div class="row"><h2 class="grow">聽力</h2>${difficulty()}</div><p class="small">${m.stars} ${m.label} · 速度會自動連動。</p><button id="listenSpeak">▶ 播放</button><p class="passage">${x.audio}</p>${x.qs.map((a,i)=>`<div class="listenNew"><h3>${i+1}. ${a[0]}</h3>${a[1].map((o,j)=>`<button class="option listenNewAnswer" data-ok="${j===a[2]}">${'ABCD'[j]}. ${o}</button>`).join('')}<div class="feedback" hidden></div></div>`).join('')}</section>`}
function words(){let d=day(),m=starMeta()[levelKey()],pool=pools[m.pool];if(!d.words||!d.words.length||d.wordLevel!==levelKey()){d.words=pool.slice().sort(()=>Math.random()-.5).slice(0,15);d.wordLevel=levelKey();save()}let favs=favoriteStore(),cats=['All',...new Set(favs.map(x=>x.category))];if(wordPane==='favorites'){return `<section class="card"><div class="row"><h2 class="grow">我的收藏</h2><button data-pane="learn">學習單字</button></div><label>分類 <select id="favFilter" class="input">${cats.map(x=>`<option>${x}</option>`).join('')}</select></label><div id="favList">${favRows(favs)}</div><h3>收藏複習</h3><button id="startFavReview">開始複習收藏</button><p class="small">錯題本仍獨立保留於資料檔，不會再混入此視窗。</p></section>`}if(wordPane==='review'){return favoriteReview()}return `<section class="card"><div class="row"><h2 class="grow">單字 · ${m.stars}</h2>${difficulty()}</div><div class="subtabs"><button class="active" data-pane="learn">今日單字</button><button data-pane="quiz">單字測驗</button><button data-pane="favorites">我的收藏 (${favs.length})</button><button data-pane="review">收藏複習</button></div>${d.words.map(w=>{let x=wi(w);return `<article class="word"><button class="favorite ${isFavorite(w)?'saved':''}" data-favorite="${w}">★</button><h3>${w}</h3><span class="ipa">${x.ipa}</span><button class="wordSpeak" data-w="${w}">🔊</button><p><b>${x.pos}</b> · ${x.en}<br>${x.zh}</p><p>${x.ex}</p></article>`}).join('')}</section>`}
function favRows(favs,category='All'){let a=category==='All'?favs:favs.filter(x=>x.category===category);return a.length?a.map(x=>`<div class="favorite-row"><span><b>${x.word}</b> · ${x.category}<br><small>${x.date}</small></span><button data-favorite="${x.word}">★</button></div>`).join(''):'<p>No saved words in this category.</p>'}
function favoriteReview(){let all=favoriteStore(),cats=['All',...new Set(all.map(x=>x.category))],f=reviewCategory==='All'?all:all.filter(x=>x.category===reviewCategory);if(!f.length)return `<section class="card"><h2>收藏複習</h2><p>此分類沒有收藏單字。</p><button data-pane="learn">返回單字</button></section>`;let x=wi(f[0].word),others=f.slice(1,4).map(a=>a.word),o=[x.w,...others].sort(()=>Math.random()-.5);return `<section class="card"><div class="row"><h2 class="grow">收藏複習</h2><button data-pane="favorites">我的收藏</button></div><label>複習分類 <select id="reviewFilter" class="input">${cats.map(c=>`<option ${c===reviewCategory?'selected':''}>${c}</option>`).join('')}</select></label><h3>Which word means「${x.zh}」?</h3>${o.map(w=>`<button class="option favAnswer" data-ok="${w===x.w}">${w}</button>`).join('')}<div class="feedback" hidden></div></section>`}
function speech(t){let u=new SpeechSynthesisUtterance(t),m=starMeta()[levelKey()];u.rate=m.rate;u.lang='en-US';speechSynthesis.cancel();speechSynthesis.speak(u)}
function render(){if(!['reading','listening','words','pet'].includes(tab))tab='reading';app.innerHTML=tab==='reading'?reading():tab==='listening'?listening():tab==='words'?words():`<section class="card"><h2>Foxy 寵物</h2><p>點右下角 Foxy 開啟聊天與互動。</p></section>`;document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));bind()}
function bind(){document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;if(tab==='pet'){$('#chat').hidden=false;showChat()}render()});document.querySelectorAll('.globalLevel').forEach(x=>x.onchange=()=>{set.level=x.value;saveSet();wordPane='learn';render()});let ns=$('#newsSpeak');if(ns)ns.onclick=()=>speech(day().news.en);let na=$('#newsAi');if(na)na.onclick=freshNews;let ls=$('#listenSpeak');if(ls)ls.onclick=()=>speech(document.querySelector('.passage').textContent);document.querySelectorAll('.wordSpeak').forEach(b=>b.onclick=()=>speech(b.dataset.w));document.querySelectorAll('[data-favorite]').forEach(b=>b.onclick=()=>addFavorite(b.dataset.favorite));document.querySelectorAll('[data-pane]').forEach(b=>b.onclick=()=>{wordPane=b.dataset.pane;render()});let filter=$('#favFilter');if(filter)filter.onchange=()=>$('#favList').innerHTML=favRows(favoriteStore(),filter.value);let rf=$('#reviewFilter');if(rf)rf.onchange=()=>{reviewCategory=rf.value;render()};document.querySelectorAll('.articleAnswer,.listenNewAnswer,.favAnswer').forEach(b=>b.onclick=()=>{let box=b.parentElement;if(box.dataset.done)return;box.dataset.done=1;let ok=b.dataset.ok==='true';b.classList.add(ok?'right':'wrong');let f=box.querySelector('.feedback');f.hidden=false;f.textContent=ok?'Correct!':'Keep going — review the related sentence.';rec(ok)});let fr=$('#startFavReview');if(fr)fr.onclick=()=>{wordPane='review';render()}}
tab='reading';if(data)render();

/* RSS reader and lively-pet base layer. */
var rssReadIndex=0,rssQuizIndex=0;
function readHistory(){try{return JSON.parse(localStorage.getItem('bright-rss-read-v1')||'[]')}catch{return []}}
function saveReadHistory(ids){localStorage.setItem('bright-rss-read-v1',JSON.stringify(ids.slice(-200)))}
function fallbackRss(){return [{id:'local-1',source:'AI fallback',title:'Cities test new cooling measures',published:q(),link:'',en:'Cities are testing reflective roofs and shaded public spaces to help residents cope with longer periods of extreme heat. Officials say the measures can lower local temperatures while reducing electricity demand.',zh:'城市正測試反射性屋頂與有遮蔭的公共空間，協助居民應對更長時間的極端高溫。官員表示，這些措施可降低局部溫度並減少用電需求。',ai:true},{id:'local-2',source:'AI fallback',title:'Public libraries expand practical services',published:q(),link:'',en:'Public libraries are lending tools and offering repair workshops so residents can complete small projects without purchasing costly equipment. The programs also emphasize safe and responsible use.',zh:'公共圖書館正在出借工具並提供維修工作坊，讓居民不必購買昂貴設備也能完成小型專案；這些計畫也強調安全且負責任的使用方式。',ai:true},{id:'local-3',source:'AI fallback',title:'Researchers examine flexible work patterns',published:q(),link:'',en:'Researchers are studying how flexible work schedules affect concentration and teamwork. Early findings suggest that clear communication matters more than the number of days spent in an office.',zh:'研究人員正探討彈性工作時程如何影響專注力與團隊合作。初步結果顯示，清楚的溝通可能比在辦公室工作的天數更重要。',ai:true}]}
function quizForArticle(a){return [{stem:`What is the main focus of “${a.title}”?`,o:['A current issue and its practical effects.','A fictional story.','A restaurant review.','A sports result.'],ans:0,why:'The question is based on the article topic and summary.'},{stem:'Which statement is supported by the article?',o:['The article describes a reported measure or finding.','The article says the issue has disappeared.','The article rejects all research.','The article contains no practical details.'],ans:0,why:'The article summary provides this information.'},{stem:'The word “practical” is closest in meaning to',o:['useful in real situations','impossible to test','unrelated to action','purely fictional'],ans:0,why:'Practical refers to usefulness in real situations.'}]}
async function loadRss(){let d=day();if(d.rssLoading||d.rssArticles)return;d.rssLoading=true;render();try{let seen=readHistory(),r=await api('/api/rss',{seen});let a=(r.articles||[]).slice(0,3);d.rssArticles=a.length>=3?a:fallbackRss();d.rssArticles.forEach(x=>x.questions=quizForArticle(x));saveReadHistory([...seen,...d.rssArticles.map(x=>x.id)]);d.rssReadIndex=0;d.rssQuizIndex=0}catch{d.rssArticles=fallbackRss();d.rssArticles.forEach(x=>x.questions=quizForArticle(x))}d.rssLoading=false;save();render()}
function reading(){let d=day();if(!d.rssArticles){setTimeout(loadRss,0);return `<section class="card"><h2>今日閱讀</h2><p>正在抓取 BBC / CNN RSS 與翻譯…</p></section>`}let articles=d.rssArticles,ri=d.rssReadIndex||0,qi=d.rssQuizIndex||0,a=articles[ri],t=articles[qi],p=proverbToday();return `<section class="card"><div class="row"><h2 class="grow">今日閱讀 ${ri+1}/${articles.length}</h2>${difficulty()}</div><p class="quote">${p[0]}<br><span class="small">${p[1]}</span></p><span class="tag">${a.source}${a.ai?' · 今日為 AI 生成內容':''}</span><h3>${a.title}</h3><p class="small">${a.published}</p><p class="passage">${a.en}</p><p class="translation">${a.zh}</p><div class="row"><button class="rssSpeak">🔊 朗讀</button><button class="rssNext">下一篇</button>${a.link?`<a href="${a.link}" target="_blank">原文連結</a>`:''}</div></section><section class="card"><div class="row"><h2 class="grow">閱讀測驗 ${qi+1}/${articles.length}</h2><button class="quizNext">下一篇測驗</button></div><p class="small">題目對應：${t.title}</p>${t.questions.map((x,i)=>`<div class="rssQ"><h3>${i+1}. ${x.stem}</h3>${x.o.map((o,j)=>`<button class="option rssAnswer" data-ok="${j===x.ans}">${'ABCD'[j]}. ${o}</button>`).join('')}<div class="feedback" hidden></div></div>`).join('')}</section>`}
function coins(){try{return JSON.parse(localStorage.getItem('bright-coins-v1')||'{"coins":0,"correct":0,"tasks":{}}')}catch{return {coins:0,correct:0,tasks:{}}}}
function saveCoins(x){localStorage.setItem('bright-coins-v1',JSON.stringify(x))}
function addCoins(n,why){let c=coins();c.coins+=n;saveCoins(c);say(`+${n} coins: ${why}`)}
function petTalk(){let d=day(),heads=(d.rssArticles||[]).map(x=>x.title),lines=[`You have studied ${d.words?.length||0} words today — nice work!`,'Do you think language shapes thought, or only expresses it?',heads.length?`News gossip: ${heads[0]} — what do you think?`:'I am saving my cleverest tail wag for your next answer.'];let text=lines[Math.floor(Math.random()*lines.length)];$('#petBubble').textContent=text;data.pet.lastPrompt=text;save()}
function schedulePetTalk(){let delay=(2+Math.random()*3)*60000;setTimeout(()=>{petTalk();schedulePetTalk()},delay)}
function petBlink(){let f=$('#petFace');if(!f)return;f.classList.add('blink');setTimeout(()=>f.classList.remove('blink'),140);setTimeout(petBlink,(3+Math.random()*5)*1000)}
function bind(){document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;if(tab==='pet'){$('#chat').hidden=false;showChat()}render()});let brand=$('#brandHome');if(brand)brand.onclick=()=>{tab='reading';render();window.scrollTo({top:0,behavior:'smooth'})};document.querySelectorAll('.globalLevel').forEach(x=>x.onchange=()=>{set.level=x.value;saveSet();render()});document.querySelectorAll('.rssSpeak').forEach(b=>b.onclick=()=>speech(day().rssArticles[day().rssReadIndex||0].en));document.querySelectorAll('.rssNext').forEach(b=>b.onclick=()=>{day().rssReadIndex=((day().rssReadIndex||0)+1)%day().rssArticles.length;save();render()});document.querySelectorAll('.quizNext').forEach(b=>b.onclick=()=>{day().rssQuizIndex=((day().rssQuizIndex||0)+1)%day().rssArticles.length;save();render()});document.querySelectorAll('.rssAnswer').forEach(b=>b.onclick=()=>{let box=b.parentElement;if(box.dataset.done)return;box.dataset.done=1;let ok=b.dataset.ok==='true';b.classList.add(ok?'right':'wrong');let f=box.querySelector('.feedback');f.hidden=false;f.textContent=ok?'Correct!':'Review the source article and try again.';let c=coins();if(ok){c.correct++;if(c.correct%5===0){c.coins+=5;say('+5 coins: five correct answers')}}saveCoins(c);rec(ok)});document.querySelectorAll('.wordSpeak').forEach(b=>b.onclick=()=>speech(b.dataset.w));document.querySelectorAll('[data-favorite]').forEach(b=>b.onclick=()=>addFavorite(b.dataset.favorite));document.querySelectorAll('[data-pane]').forEach(b=>b.onclick=()=>{wordPane=b.dataset.pane;render()});let f=$('#favFilter');if(f)f.onchange=()=>$('#favList').innerHTML=favRows(favoriteStore(),f.value);let rf=$('#reviewFilter');if(rf)rf.onchange=()=>{reviewCategory=rf.value;render()};document.querySelectorAll('.favAnswer').forEach(b=>b.onclick=()=>{b.classList.add(b.dataset.ok==='true'?'right':'wrong');rec(b.dataset.ok==='true')})}
setTimeout(()=>{let pet=$('#pet');if(pet)pet.onclick=()=>{let bubble=$('#petBubble');if(bubble)bubble.textContent='Foxy: 哈哈！我聽見你了。';say('Tap the Pet tab to chat with Foxy.');};petBlink();schedulePetTalk()},0);
document.addEventListener('click',e=>{let t=e.target.closest('#listenSpeak,.listenNewAnswer,#startFavReview');if(!t)return;if(t.id==='listenSpeak'){let p=document.querySelector('.passage');if(p)speech(p.textContent);return}if(t.id==='startFavReview'){wordPane='review';render();return}if(t.classList.contains('listenNewAnswer')){let box=t.parentElement;if(box.dataset.done)return;box.dataset.done=1;let ok=t.dataset.ok==='true';t.classList.add(ok?'right':'wrong');let f=box.querySelector('.feedback');f.hidden=false;f.textContent=ok?'Correct!':'Listen once more and try again.';rec(ok)}});

/* Stable tab panels, long material, and in-page favourite editor. */
function longKey(a){return `long-${a.id}`}
async function ensureLong(){let d=day(),a=d.rssArticles&&d.rssArticles[d.rssQuizIndex||0];if(!a)return;let key=longKey(a);if(d[key]||d.longLoading)return;d.longLoading=true;render();let r=await api('/api/longread',{article:a,difficulty:starMeta()[levelKey()].label});if(r.result){d[key]=r.result;d[key].status='ready'}else d[key]={status:'failed',error:r.error||'AI long-read generation is unavailable'};d.longLoading=false;save();render()}
function reading(){let d=day();if(!d.rssArticles){setTimeout(loadRss,0);return `<section class="card"><h2>今日閱讀</h2><p>正在載入 RSS 新聞…</p></section>`}let a=d.rssArticles[d.rssReadIndex||0],qa=d.rssArticles[d.rssQuizIndex||0],key=longKey(qa),long=d[key];if(!long&&!d.longLoading)setTimeout(ensureLong,0);return `<section class="card"><div class="row"><h2 class="grow">今日閱讀 ${(d.rssReadIndex||0)+1}/${d.rssArticles.length}</h2>${difficulty()}</div><span class="tag">${a.source}${a.ai?' · 今日為 AI 生成內容':''}</span><h3>${a.title}</h3><p class="small">${a.published}</p><p class="passage">${a.en}</p><h3>中文翻譯</h3><p class="translation">${a.zh}</p><div class="row"><button class="rssSpeak">🔊 朗讀</button><button class="rssNext">下一篇</button>${a.link?`<a class="sourceLink" href="${a.link}" target="_blank" rel="noopener">原文連結 ↗</a>`:''}</div></section><section class="card"><div class="row"><h2 class="grow">閱讀測驗 ${(d.rssQuizIndex||0)+1}/${d.rssArticles.length}</h2><button class="quizNext">下一篇測驗</button></div>${d.longLoading?'<p>正在一次生成 600+ 字長文與完整題組…</p>':''}${long&&long.status==='failed'?`<p class="feedback">${long.error}</p>`:''}${long&&long.status==='ready'?`<p class="small">測驗長文 · ${qa.title}</p><p class="passage">${long.en}</p><details><summary>查看中文翻譯</summary><p class="translation">${long.zh}</p></details>${long.questions.map((x,i)=>`<div class="longQ"><h3>${i+1}. ${x.stem}</h3>${x.o.map((o,j)=>`<button class="option longAnswer" data-ok="${j===x.ans}">${'ABCD'[j]}. ${o}</button>`).join('')}<div class="feedback" hidden></div></div>`).join('')}`:''}</section>`}
function listening(){let text=`Good morning, everyone. This is Maya Chen from the regional operations office. I am calling with an update about Thursday’s client workshop, which had originally been scheduled for the downtown conference center. Because the center will be repairing its ventilation system, the workshop has been moved to the Riverside Hotel, two blocks from our usual location. Registration will still begin at eight forty-five, and the first presentation will start promptly at nine fifteen. Please bring the revised project brief that was emailed yesterday, not the earlier draft. Attendees who need parking should contact the hotel directly before Wednesday afternoon, because spaces are limited. After the workshop, a short feedback survey will be sent to everyone who signed in.`;let qs=[['Why was the location changed?',['The conference center needs repairs.','The hotel offered free rooms.','The client canceled the workshop.','The office is moving.'],0],['What should attendees bring?',['The revised project brief.','A parking receipt.','The original draft.','A hotel reservation.'],0],['When does the first presentation begin?',['At 9:15.','At 8:45.','On Wednesday afternoon.','After the survey.'],0],['Who should contact the hotel?',['People who need parking.','All speakers.','Only clients.','Survey participants.'],0]];return `<section class="card"><div class="row"><h2 class="grow">聽力 · 120+ words</h2>${difficulty()}</div><button id="listenSpeak">▶ 播放</button><p class="passage">${text}</p>${qs.map((x,i)=>`<div class="listenNew"><h3>${i+1}. ${x[0]}</h3>${x[1].map((o,j)=>`<button class="option listenNewAnswer" data-ok="${j===x[2]}">${'ABCD'[j]}. ${o}</button>`).join('')}<div class="feedback" hidden></div></div>`).join('')}</section>`}
function favPanel(words){return words.map(w=>{let x=wi(w);return `<article class="word"><button class="favorite ${isFavorite(w)?'saved':''}" data-favorite="${w}">★</button><h3>${w}</h3><span class="ipa">${x.ipa}</span><button class="wordSpeak" data-w="${w}">🔊</button><p><b>${x.pos}</b> · ${x.en}<br>${x.zh}</p><p>${x.ex}</p></article>`}).join('')}
function words(){let d=day(),m=starMeta()[levelKey()],pool=pools[m.pool];if(!d.words||!d.words.length||d.wordLevel!==levelKey()){d.words=pool.slice().sort(()=>Math.random()-.5).slice(0,15);d.wordLevel=levelKey();save()}let favs=favoriteStore(),cats=['All',...new Set(favs.map(x=>x.category))];let quiz=d.words.slice(0,5);return `<section class="card"><div class="row"><h2 class="grow">單字 · ${m.stars}</h2>${difficulty()}</div><div class="subtabs"><button data-pane="learn">今日單字</button><button data-pane="quiz">單字測驗</button><button data-pane="favorites">我的收藏 (${favs.length})</button><button data-pane="review">收藏複習</button></div><div class="wordSection" data-section="learn" ${wordPane==='learn'?'':'hidden'}>${favPanel(d.words)}</div><div class="wordSection" data-section="quiz" ${wordPane==='quiz'?'':'hidden'}>${quiz.map(w=>{let x=wi(w);return `<article class="word"><h3>Which word means「${x.zh}」?</h3><button class="option vocabInline" data-ok="true">${w}</button><button class="option vocabInline" data-ok="false">${quiz.find(z=>z!==w)||'agenda'}</button></article>`}).join('')}</div><div class="wordSection" data-section="favorites" ${wordPane==='favorites'?'':'hidden'}><label>分類 <select id="favFilter" class="input">${cats.map(c=>`<option>${c}</option>`).join('')}</select></label><div id="favList">${favRows(favs)}</div><div id="categoryManager"><h3>管理分類</h3>${cats.filter(c=>c!=='All').map(c=>`<div class="favorite-row"><b>${c}</b><span><button class="renameCat" data-cat="${c}">重新命名</button><button class="deleteCat" data-cat="${c}">刪除</button></span></div>`).join('')}</div></div><div class="wordSection" data-section="review" ${wordPane==='review'?'':'hidden'}>${favoriteReview()}</div></section>`}
function switchWordPane(name){wordPane=name;document.querySelectorAll('.wordSection').forEach(e=>e.hidden=e.dataset.section!==name);document.querySelectorAll('[data-pane]').forEach(b=>b.classList.toggle('active',b.dataset.pane===name))}
function openFavoriteEditor(w){let existing=document.querySelector('.favEdit');if(existing)existing.remove();let card=[...document.querySelectorAll('.word')].find(x=>x.querySelector(`[data-favorite="${w}"]`));if(!card)return;let cats=[...new Set(['重要','易錯','待複習',...favoriteStore().map(x=>x.category)])];let panel=document.createElement('div');panel.className='favEdit feedback';panel.innerHTML=`<b>收藏 ${w}</b><div>${cats.map(c=>`<button class="pickCat" data-cat="${c}">${c}</button>`).join('')}</div><input class="newCat" placeholder="新增自訂分類"><button class="saveFav">確認收藏</button><button class="cancelFav">取消</button>`;card.append(panel);let selected=cats[0];panel.querySelectorAll('.pickCat').forEach(b=>b.onclick=()=>{selected=b.dataset.cat;panel.querySelectorAll('.pickCat').forEach(x=>x.classList.toggle('active',x===b))});panel.querySelector('.cancelFav').onclick=()=>panel.remove();panel.querySelector('.saveFav').onclick=()=>{let category=panel.querySelector('.newCat').value.trim()||selected,a=favoriteStore().filter(x=>x.word!==w);a.push({word:w,category:category.slice(0,30),date:q()});saveFavorites(a);panel.remove();switchWordPane('learn');render()}}
function renameCategory(old){let row=document.querySelector(`.renameCat[data-cat="${old}"]`).closest('.favorite-row'),input=document.createElement('input');input.value=old;let ok=document.createElement('button');ok.textContent='儲存';row.append(input,ok);ok.onclick=()=>{let next=input.value.trim();if(!next)return;saveFavorites(favoriteStore().map(x=>x.category===old?{...x,category:next}:x));render()}}
function deleteCategory(cat){saveFavorites(favoriteStore().map(x=>x.category===cat?{...x,category:'待複習'}:x));render()}
function bind(){document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;if(tab==='pet'){$('#chat').hidden=false;showChat()}render()});let brand=$('#brandHome');if(brand)brand.onclick=()=>{tab='reading';render()};document.querySelectorAll('.globalLevel').forEach(x=>x.onchange=()=>{set.level=x.value;saveSet();render()});document.querySelectorAll('.rssSpeak').forEach(b=>b.onclick=()=>speech(day().rssArticles[day().rssReadIndex||0].en));document.querySelectorAll('.rssNext').forEach(b=>b.onclick=()=>{day().rssReadIndex=((day().rssReadIndex||0)+1)%day().rssArticles.length;save();render()});document.querySelectorAll('.quizNext').forEach(b=>b.onclick=()=>{day().rssQuizIndex=((day().rssQuizIndex||0)+1)%day().rssArticles.length;save();render()});document.querySelectorAll('.wordSpeak').forEach(b=>b.onclick=()=>speech(b.dataset.w));document.querySelectorAll('[data-favorite]').forEach(b=>b.onclick=()=>openFavoriteEditor(b.dataset.favorite));document.querySelectorAll('[data-pane]').forEach(b=>b.onclick=()=>switchWordPane(b.dataset.pane));let f=$('#favFilter');if(f)f.onchange=()=>$('#favList').innerHTML=favRows(favoriteStore(),f.value);document.querySelectorAll('.renameCat').forEach(b=>b.onclick=()=>renameCategory(b.dataset.cat));document.querySelectorAll('.deleteCat').forEach(b=>b.onclick=()=>deleteCategory(b.dataset.cat));document.querySelectorAll('.longAnswer,.listenNewAnswer,.vocabInline,.favAnswer').forEach(b=>b.onclick=()=>{let box=b.parentElement;if(box.dataset.done)return;box.dataset.done=1;let ok=b.dataset.ok==='true';b.classList.add(ok?'right':'wrong');let feed=box.querySelector('.feedback');if(feed){feed.hidden=false;feed.textContent=ok?'Correct!':'Try the next one.'}rec(ok)});document.querySelectorAll('.rssAnswer').forEach(b=>b.onclick=()=>{let box=b.parentElement;if(box.dataset.done)return;box.dataset.done=1;b.classList.add(b.dataset.ok==='true'?'right':'wrong');rec(b.dataset.ok==='true')})}

/* Dashboard and stable same-page panels.  These definitions intentionally sit last: the
   project keeps earlier data helpers, while the UI layer is upgraded without migration. */
function dashboard(){
  let d=day(), c=coins(), s=data.stats||{study_dates:[]}, mistakes=(data.mistakes||[]).filter(x=>x.hits<2).length, favs=favoriteStore().length;
  let tasks=[['閱讀','reading',d.readingDone],['聽力','listening',d.listeningDone],['單字','words',d.wordDone],['單字測驗','words',d.vocabDone]];
  return `<section class="card dashHero"><div><p class="quote">Small steps, bright results.</p><h1>今日學習 Dashboard</h1><p>把零碎時間，變成穩定的英文進步。</p><div class="progress"><b style="width:${taskProgress()*20}%"></b></div></div><button class="dashPetButton" data-go="pet" aria-label="前往寵物頁"><span class="dashFox">🦊</span><span>Foxy 在等你</span></button></section>
  <section class="dashboardGrid">${tasks.map(x=>`<article class="card dashMetric"><span>${x[0]}</span><b>${x[2]?'✓ 已完成':'○ 待完成'}</b><button data-go="${x[1]}">前往</button></article>`).join('')}</section>
  <section class="dashboardGrid dashboardStats"><article class="card dashMetric"><span>連續學習</span><b>${d.streak||0} 天</b></article><article class="card dashMetric"><span>金幣</span><b>🪙 ${c.coins||0}</b></article><article class="card dashMetric"><span>錯題</span><b>${mistakes}</b></article><article class="card dashMetric"><span>已收藏單字</span><b>★ ${favs}</b></article></section>
  <section class="card quickLinks"><h2>快速入口</h2><button data-go="reading">📖 閱讀</button><button data-go="listening">🎧 聽力</button><button data-go="words">🌱 單字</button><button data-go="pet">🦊 寵物</button><p class="small">累積學習天數：${(s.study_dates||[]).length} 天</p></section>`;
}
function petPage(){
  let p=data.pet||{mood:65,food:0};
  return `<section class="card petPage"><div class="petStage"><div class="petFull" id="petStageFox" role="button" tabindex="0" aria-label="和 Foxy 互動"><div class="foxEars">▲ ▲</div><div class="foxHead"><span class="petEye">•</span><span class="petNose">●</span><span class="petEye">•</span></div><div class="foxBody">🦊</div><div class="foxTail">〰</div></div><p id="stagePetSpeech" class="stagePetSpeech">${p.lastPrompt||'今天想從哪一個英文任務開始？'}</p><p class="small">點一下 Foxy，牠會跳起來並回應你。</p></div></section>
  <section class="card petInfo"><h2>Foxy 的狀態</h2><div class="dashboardGrid"><div class="dashMetric"><span>心情</span><b>${p.mood||65} / 100</b></div><div class="dashMetric"><span>飼料</span><b>🍪 ${p.food||0}</b></div></div><button id="openPetChat">和 Foxy 聊聊天</button></section>`;
}
function words(){
  let d=day(),m=starMeta()[levelKey()],pool=pools[m.pool];
  if(!d.words||!d.words.length||d.wordLevel!==levelKey()){d.words=pool.slice().sort(()=>Math.random()-.5).slice(0,15);d.wordLevel=levelKey();save()}
  let favs=favoriteStore(),cats=['All',...new Set(favs.map(x=>x.category))],quiz=d.words.slice(0,5),reviewWords=(reviewCategory==='All'?favs:favs.filter(x=>x.category===reviewCategory));
  let reviewContent=reviewWords.length?(()=>{let x=wi(reviewWords[0].word),choices=[x.w,...reviewWords.slice(1,4).map(v=>v.word)].sort(()=>Math.random()-.5);return `<label>分類 <select id="reviewFilter" class="input">${cats.map(c=>`<option ${c===reviewCategory?'selected':''}>${c}</option>`).join('')}</select></label><h3>Which word means「${x.zh}」?</h3>${choices.map(w=>`<button class="option favAnswer" data-ok="${w===x.w}">${w}</button>`).join('')}<div class="feedback" hidden></div>`})():`<p>這個分類還沒有收藏單字。</p>`;
  return `<section class="card wordShell"><div class="row"><h2 class="grow">單字 · ${m.stars}</h2>${difficulty()}</div><div class="subtabs wordTabs" role="tablist"><button data-pane="learn">今日單字</button><button data-pane="quiz">單字測驗</button><button data-pane="favorites">我的收藏 (${favs.length})</button><button data-pane="review">收藏複習</button></div>
  <div class="wordContent"><div class="wordSection" data-section="learn">${favPanel(d.words)}</div><div class="wordSection" data-section="quiz" hidden>${quiz.map(w=>{let x=wi(w),other=quiz.find(z=>z!==w)||'agenda';return `<article class="word"><h3>Which word means「${x.zh}」?</h3><button class="option vocabInline" data-ok="true">${w}</button><button class="option vocabInline" data-ok="false">${other}</button><div class="feedback" hidden></div></article>`}).join('')}</div><div class="wordSection" data-section="favorites" hidden><label>分類 <select id="favFilter" class="input">${cats.map(c=>`<option>${c}</option>`).join('')}</select></label><div id="favList">${favRows(favs)}</div><div id="categoryManager" class="categoryManager"><h3>管理分類</h3>${cats.filter(c=>c!=='All').map(c=>`<div class="favorite-row"><b>${c}</b><span><button class="renameCat" data-cat="${c}">重新命名</button><button class="deleteCat" data-cat="${c}">刪除</button></span></div>`).join('')}</div></div><div class="wordSection" data-section="review" hidden>${reviewContent}</div></div></section>`;
}
function switchWordPane(name){wordPane=name;document.querySelectorAll('.wordSection').forEach(e=>e.hidden=e.dataset.section!==name);document.querySelectorAll('[data-pane]').forEach(b=>b.classList.toggle('active',b.dataset.pane===name))}
async function loadRss(){let d=day();if(d.rssLoading||d.rssArticles)return;d.rssLoading=true;render();try{let seen=readHistory(),r=await api('/api/rss',{seen});let a=(r.articles||[]).slice(0,3);d.rssArticles=a.length>=3?a:fallbackRss();d.communityArticles=Array.isArray(r.community)?r.community:[];d.rssArticles.forEach(x=>x.questions=quizForArticle(x));saveReadHistory([...seen,...d.rssArticles.map(x=>x.id)]);d.rssReadIndex=0;d.rssQuizIndex=0}catch{d.rssArticles=fallbackRss();d.communityArticles=[];d.rssArticles.forEach(x=>x.questions=quizForArticle(x))}d.rssLoading=false;save();render()}
function reading(){let d=day();if(!d.rssArticles){setTimeout(loadRss,0);return `<section class="card"><h2>今日閱讀</h2><p>正在安全載入 RSS 新聞…</p></section>`}let a=d.rssArticles[d.rssReadIndex||0],qa=d.rssArticles[d.rssQuizIndex||0],key=longKey(qa),long=d[key],community=d.communityArticles||[];if(!long&&!d.longLoading)setTimeout(ensureLong,0);return `<section class="card"><div class="row"><h2 class="grow">今日閱讀 ${(d.rssReadIndex||0)+1}/${d.rssArticles.length}</h2>${difficulty()}</div><span class="tag">${a.source}${a.ai?' · 今日為 AI 生成內容':''}</span><h3>${a.title}</h3><p class="small">${a.published}</p><p class="passage">${a.en}</p><h3>中文翻譯</h3><p class="translation">${a.zh}</p><div class="row"><button class="rssSpeak">🔊 朗讀</button><button class="rssNext">下一篇</button>${a.link?`<a class="sourceLink" href="${a.link}" target="_blank" rel="noopener">原文連結 ↗</a>`:''}</div></section><section class="card communityCard"><h2>社群補充</h2>${community.length?community.map(x=>`<article class="communityItem"><span class="tag">${x.source}</span><a href="${x.link}" target="_blank" rel="noopener"><b>${x.title}</b></a><p class="small">u/${x.author||'unknown'} · ${x.published||''}</p></article>`).join(''):'<p class="small">暫無社群內容</p>'}</section><section class="card"><div class="row"><h2 class="grow">閱讀測驗 ${(d.rssQuizIndex||0)+1}/${d.rssArticles.length}</h2><button class="quizNext">下一篇測驗</button></div>${d.longLoading?'<p>正在一次生成 600+ 字長文與完整題組…</p>':''}${long&&long.status==='failed'?`<p class="feedback">${long.error}</p>`:''}${long&&long.status==='ready'?`<p class="small">測驗長文 · ${qa.title}</p><p class="passage">${long.en}</p><details><summary>查看中文翻譯</summary><p class="translation">${long.zh}</p></details>${long.questions.map((x,i)=>`<div class="longQ"><h3>${i+1}. ${x.stem}</h3>${x.o.map((o,j)=>`<button class="option longAnswer" data-ok="${j===x.ans}">${'ABCD'[j]}. ${o}</button>`).join('')}<div class="feedback" hidden></div></div>`).join('')}`:''}</section>`}
function bind(){
  document.querySelectorAll('[data-tab],[data-go]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab||b.dataset.go;render();window.scrollTo({top:0,behavior:'smooth'})});
  let brand=$('#brandHome');if(brand)brand.onclick=()=>{tab='dashboard';render();window.scrollTo({top:0,behavior:'smooth'})};
  document.querySelectorAll('.globalLevel').forEach(x=>x.onchange=()=>{set.level=x.value;saveSet();render()});
  document.querySelectorAll('.rssSpeak').forEach(b=>b.onclick=()=>speech(day().rssArticles[day().rssReadIndex||0].en));
  document.querySelectorAll('.rssNext').forEach(b=>b.onclick=()=>{let d=day();d.rssReadIndex=((d.rssReadIndex||0)+1)%d.rssArticles.length;save();render()});
  document.querySelectorAll('.quizNext').forEach(b=>b.onclick=()=>{let d=day();d.rssQuizIndex=((d.rssQuizIndex||0)+1)%d.rssArticles.length;save();render()});
  document.querySelectorAll('.wordSpeak').forEach(b=>b.onclick=()=>speech(b.dataset.w));document.querySelectorAll('[data-favorite]').forEach(b=>b.onclick=()=>openFavoriteEditor(b.dataset.favorite));document.querySelectorAll('[data-pane]').forEach(b=>b.onclick=()=>switchWordPane(b.dataset.pane));
  let f=$('#favFilter');if(f)f.onchange=()=>$('#favList').innerHTML=favRows(favoriteStore(),f.value);let rf=$('#reviewFilter');if(rf)rf.onchange=()=>{reviewCategory=rf.value;render()};document.querySelectorAll('.renameCat').forEach(b=>b.onclick=()=>renameCategory(b.dataset.cat));document.querySelectorAll('.deleteCat').forEach(b=>b.onclick=()=>deleteCategory(b.dataset.cat));
  document.querySelectorAll('.longAnswer,.listenNewAnswer,.vocabInline,.favAnswer,.rssAnswer').forEach(b=>b.onclick=()=>{let box=b.parentElement;if(box.dataset.done)return;box.dataset.done=1;let ok=b.dataset.ok==='true';b.classList.add(ok?'right':'wrong');let feed=box.querySelector('.feedback');if(feed){feed.hidden=false;feed.textContent=ok?'Correct!':'Keep going — review the related sentence.'}rec(ok)});
  let stage=$('#petStageFox');if(stage){let react=()=>{stage.classList.remove('petCelebrate');void stage.offsetWidth;stage.classList.add('petCelebrate');let t=['尾巴收到你的招呼！','你回來了，我們一起練英文。','今天的一小題，也算進步。'];$('#stagePetSpeech').textContent=t[Math.floor(Math.random()*t.length)];let h=$('#hearts');if(h){h.textContent='♥';h.classList.add('petHeart');setTimeout(()=>{h.textContent='';h.classList.remove('petHeart')},1000)}};stage.onclick=react;stage.onkeydown=e=>{if(e.key==='Enter'||e.key===' ')react()}}
  let chat=$('#openPetChat');if(chat)chat.onclick=()=>{$('#chat').hidden=false;showChat()};
}
function render(){if(!['dashboard','reading','listening','words','pet'].includes(tab))tab='dashboard';let view={dashboard,reading,listening,words,pet:petPage}[tab];try{app.innerHTML=view()}catch(e){console.error(e);app.innerHTML='<section class="card"><h2>載入發生問題</h2><p>已保留本機資料；請重新整理後再試。</p></section>'}document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));bind()}

/* Restore the pre-daily-AI dashboard and vocabulary presentation. */
function favoriteStore(){try{return JSON.parse(localStorage.getItem('bright-favorites-v1')||'[]')}catch{return []}}
function saveFavorites(items){localStorage.setItem('bright-favorites-v1',JSON.stringify(items))}
function dashboard(){let d=day(),done=taskProgress(),p=done*20,c=coins(),f=favoriteStore().length;return `<section class="card hero"><div><p class="quote">Small steps, bright results.</p><h1>Today with Foxy</h1><p>Coins: <b>${c.coins||0}</b> · Saved words: <b>${f}</b></p><div class="progress"><b style="width:${p}%"></b></div><p class="small">Daily completion: ${p}%</p></div><button class="dashPetButton" data-go="pet"><span class="dashFox">🦊</span><span>Foxy</span></button></section><section class="card"><h2>Daily tasks</h2>${[['reading','Reading',d.readingDone],['listening','Listening',d.listeningDone],['words','Daily words',d.wordDone]].map(x=>`<div class="task"><b>${x[1]} ${x[2]?'<span class="tag">Done</span>':''}</b><button data-go="${x[0]}">Open</button></div>`).join('')}</section>`}
function words(){let d=day(),m=starMeta()[levelKey()],pool=pools[m.pool];if(!d.words||!d.words.length||d.wordLevel!==levelKey()){d.words=pool.slice().sort(()=>Math.random()-.5).slice(0,15);d.wordLevel=levelKey();save()}let favs=favoriteStore(),cats=['All',...new Set(favs.map(x=>x.category))],quiz=d.words.slice(0,5);return `<section class="card"><div class="row"><h2 class="grow">Words · ${m.stars}</h2>${difficulty()}</div><div class="subtabs"><button data-pane="learn">Today’s words</button><button data-pane="quiz">Vocabulary quiz</button><button data-pane="favorites">My favorites (${favs.length})</button><button data-pane="review">Favorite review</button></div><div class="wordSection" data-section="learn">${favPanel(d.words)}</div><div class="wordSection" data-section="quiz" hidden>${quiz.map(w=>{let x=wi(w);return `<article class="word"><h3>Which word means「${x.zh}」?</h3><button class="option vocabInline" data-ok="true">${w}</button><button class="option vocabInline" data-ok="false">${quiz.find(z=>z!==w)||'agenda'}</button></article>`}).join('')}</div><div class="wordSection" data-section="favorites" hidden><label>Category <select id="favFilter" class="input">${cats.map(c=>`<option>${c}</option>`).join('')}</select></label><div id="favList">${favRows(favs)}</div></div><div class="wordSection" data-section="review" hidden>${favoriteReview()}</div></section>`}
function openFavoriteEditor(w){let existing=document.querySelector('.favEdit');if(existing)existing.remove();let card=[...document.querySelectorAll('.word')].find(x=>x.querySelector(`[data-favorite="${w}"]`));if(!card)return;let panel=document.createElement('div');panel.className='favEdit feedback';panel.innerHTML='<label>Category <select class="favCategory"><option>Important</option><option>Easy to miss</option><option>To review</option></select></label><button class="saveFav">Save</button><button class="cancelFav">Cancel</button>';card.append(panel);panel.querySelector('.cancelFav').onclick=()=>panel.remove();panel.querySelector('.saveFav').onclick=()=>{let all=favoriteStore().filter(x=>x.word!==w);all.push({word:w,category:panel.querySelector('.favCategory').value,date:q()});saveFavorites(all);panel.remove();render()}}

/* Daily AI collections: generate only the selected difficulty, one item at a time. */
var readingMode=localStorage.getItem('bright-reading-mode')||'learn';
function aiSetKey(kind){return `daily-ai-${kind}-${levelKey()}`}
async function aiRequest(kind,index){let response=await fetch('/api/daily-ai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({kind,difficulty:levelKey(),index})});let payload=await response.json().catch(()=>({error:'Invalid server response'}));return {status:response.status,...payload}}
async function ensureAiSet(kind){let d=day(),key=aiSetKey(kind),total=kind==='listening'?1:3;if(d[key]||d.aiGenerating||d.aiQuota)return;d.aiGenerating={kind,done:0,total};render();let items=[];for(let i=0;i<total;i++){let r;try{r=await aiRequest(kind,i)}catch{r={error:'Network error'}}if(r.status===429){d.aiQuota=true;d.aiGenerating=null;save();render();return}if(r.result){items.push(r.result);d.aiGenerating.done=i+1;render()}else{items.push({status:'failed',error:r.error||'未达规格'})}}d[key]=items;d.aiGenerating=null;save();render()}
function aiProgress(kind){let d=day(),g=d.aiGenerating;if(g&&g.kind===kind)return `<p class="generation">正在生成第 ${g.done+1}/${g.total} 篇…</p>`;if(d.aiQuota)return '<p class="feedback qualityWarn">AI 额度暂时用尽，请稍后再试。</p>';return ''}
function showAiItem(item,kind,index){if(!item)return '';if(item.status==='failed')return `<p class="feedback qualityWarn">未达规格：${item.error}</p>`;let q=item.questions||[];return `<article class="aiArticle"><div class="row"><span class="qualityBadge ${item.status==='seed'?'qualityWarn':''}">${item.validation?.word_count||0} 词 · ${levelStars()}${item.status==='seed'?' · 本次为种子内容':''}</span><span class="tag">第 ${index+1} 篇</span></div><h3>${item.topic||'English learning article'}</h3><p class="passage">${item.en||''}</p><details><summary>完整中文翻译</summary><p class="translation">${item.zh||''}</p></details>${kind==='reading'?'':`<section class="questionSet">${q.map((x,qi)=>`<div class="aiQuestion"><h3>${qi+1}. ${x.stem}</h3>${x.o.map((o,oi)=>`<button class="option aiAnswer" data-kind="${kind}" data-index="${index}" data-question="${qi}" data-ok="${oi===x.ans}" data-why="${x.why}">${'ABCD'[oi]}. ${o}</button>`).join('')}<div class="feedback" hidden></div></div>`).join('')}</section>`}</article>`}
function reading(){let d=day(),kind=readingMode==='quiz'?'quiz':'reading',key=aiSetKey(kind),items=d[key];if(!items&&!d.aiGenerating)setTimeout(()=>ensureAiSet(kind),0);return `<section class="card"><div class="row"><h2 class="grow">AI 长文阅读</h2>${difficulty()}</div><div class="subtabs"><button class="${readingMode==='learn'?'active':''}" data-ai-mode="learn">阅读文章（3篇）</button><button class="${readingMode==='quiz'?'active':''}" data-ai-mode="quiz">阅读测验（3篇／12题）</button></div><p class="small">只会按目前难度生成当前分区；切换星等会建立独立的当日快取。</p>${aiProgress(kind)}${items?items.map((item,i)=>showAiItem(item,kind,i)).join(''):''}</section>`}
function listening(){let d=day(),kind='listening',key=aiSetKey(kind),items=d[key];if(!items&&!d.aiGenerating)setTimeout(()=>ensureAiSet(kind),0);return `<section class="card"><div class="row"><h2 class="grow">AI 听力长文</h2>${difficulty()}</div><p class="small">本难度 1 篇、4 题；语速会跟随星等。</p>${aiProgress(kind)}${items&&items[0]?`<button id="dailyListenSpeak">播放英文</button>${showAiItem(items[0],kind,0)}`:''}</section>`}
function wordData(value){if(typeof value==='object'&&value)return {...wi(value.word),...value};return wi(value)}
function favoriteStore(){try{return JSON.parse(localStorage.getItem('bright-favorites-v1')||'[]').map(x=>typeof x==='string'?{...wi(x),word:x,category:'待复习',date:q()}:({...wi(x.word),...x}))}catch{return []}}
function saveFavorites(items){localStorage.setItem('bright-favorites-v1',JSON.stringify(items))}
function wordCard(value){let x=wordData(value),saved=isFavorite(x.word);return `<article class="word wordCard"><button class="favorite ${saved?'saved':''}" data-favorite="${x.word}">★</button><h3>${x.word}</h3><span class="ipa">${x.ipa||''}</span><button class="wordSpeak" data-w="${x.word}">🔊</button><p><b>${x.pos||''}</b> · ${x.en||''}<br><b>中文：</b>${x.zh||'（释义待补）'}</p><p>${x.ex||''}</p></article>`}
function words(){let d=day(),m=starMeta()[levelKey()],pool=pools[m.pool];if(!d.words||!d.words.length||d.wordLevel!==levelKey()){d.words=pool.slice().sort(()=>Math.random()-.5).slice(0,15);d.wordLevel=levelKey();save()}let favs=favoriteStore(),cats=['All',...new Set(favs.map(x=>x.category))],quiz=d.words.slice(0,5);return `<section class="card wordShell"><div class="row"><h2 class="grow">单字 · ${m.stars}</h2>${difficulty()}</div><div class="subtabs wordTabs"><button data-pane="learn">今日单字</button><button data-pane="quiz">单字测验</button><button data-pane="favorites">我的收藏 (${favs.length})</button><button data-pane="review">收藏复习</button></div><div class="wordContent"><div class="wordSection wordGrid" data-section="learn">${d.words.map(wordCard).join('')}</div><div class="wordSection" data-section="quiz" hidden>${quiz.map(w=>{let x=wi(w),other=quiz.find(z=>z!==w)||'agenda';return `<article class="word"><h3>Which word means「${x.zh}」?</h3><button class="option vocabInline" data-ok="true">${w}</button><button class="option vocabInline" data-ok="false">${other}</button><div class="feedback" hidden></div></article>`}).join('')}</div><div class="wordSection wordGrid" data-section="favorites" hidden>${favs.map(wordCard).join('')||'<p>尚未收藏单字。</p>'}</div><div class="wordSection" data-section="review" hidden><label>分类 <select id="reviewFilter" class="input">${cats.map(c=>`<option>${c}</option>`).join('')}</select></label><p>从收藏夹选择分类后即可复习。</p></div></div></section>`}
function openFavoriteEditor(word){let card=[...document.querySelectorAll('.wordCard')].find(x=>x.querySelector(`[data-favorite="${word}"]`));if(!card)return;let old=card.querySelector('.favEdit');if(old){old.remove();return}let x=wordData(word),panel=document.createElement('div');panel.className='favEdit feedback';panel.innerHTML='<label>收藏分类 <select class="favCategory"><option>重要</option><option>易错</option><option>待复习</option></select></label><button class="saveFav">确认收藏</button><button class="cancelFav">取消</button>';card.append(panel);panel.querySelector('.cancelFav').onclick=()=>panel.remove();panel.querySelector('.saveFav').onclick=()=>{let category=panel.querySelector('.favCategory').value;let all=favoriteStore().filter(v=>v.word!==word);all.push({...x,word,category,date:q()});saveFavorites(all);panel.remove();render()}}
function dashboard(){let d=day(),c=coins(),f=favoriteStore().length;return `<section class="card dashHero"><div><p class="quote">Small steps, bright results.</p><h1>今日学习 Dashboard</h1><p>金币 ${c.coins||0} · 收藏 ${f} · 错题 ${(data.mistakes||[]).filter(x=>x.hits<2).length}</p></div><div class="mascot">🦊</div></section><section class="card"><h2>今日操作</h2><button data-go="reading">阅读</button><button data-go="listening">听力</button><button data-go="words">单字</button><button id="resetToday">重置今日进度</button></section>`}
function resetModal(){let modal=document.createElement('div');modal.id='resetModal';modal.className='modalShade';modal.innerHTML='<div class="resetDialog"><h2>重置今日进度？</h2><p>会清除今日 AI 文章、听力、单字与答题纪录；收藏、错题本、金币、宠物与连续学习天数都会保留。</p><button id="confirmReset">确认重置</button><button id="cancelReset">取消</button></div>';document.body.append(modal);$('#cancelReset').onclick=()=>modal.remove();$('#confirmReset').onclick=async()=>{let r=await fetch('/api/reset-today',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'}).then(x=>x.json()).catch(()=>({}));if(r.data)data=r.data;localStorage.removeItem('bright-rss-read-v1');readingMode='learn';tab='dashboard';modal.remove();render();say('今日进度已重置，正在准备新内容。')}}
function bind(){document.querySelectorAll('[data-tab],[data-go]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab||b.dataset.go;render();window.scrollTo({top:0,behavior:'smooth'})});let brand=$('#brandHome');if(brand)brand.onclick=()=>{tab='dashboard';render()};document.querySelectorAll('.globalLevel').forEach(x=>x.onchange=()=>{set.level=x.value;saveSet();render()});document.querySelectorAll('[data-ai-mode]').forEach(b=>b.onclick=()=>{readingMode=b.dataset.aiMode;localStorage.setItem('bright-reading-mode',readingMode);render()});let reset=$('#resetToday');if(reset)reset.onclick=resetModal;let ls=$('#dailyListenSpeak');if(ls)ls.onclick=()=>{let a=day()[aiSetKey('listening')]?.[0];if(a)speech(a.en)};document.querySelectorAll('.wordSpeak').forEach(b=>b.onclick=()=>speech(b.dataset.w));document.querySelectorAll('[data-favorite]').forEach(b=>b.onclick=()=>openFavoriteEditor(b.dataset.favorite));document.querySelectorAll('[data-pane]').forEach(b=>b.onclick=()=>switchWordPane(b.dataset.pane));document.querySelectorAll('.aiAnswer,.vocabInline').forEach(b=>b.onclick=()=>{let box=b.parentElement;if(box.dataset.done)return;box.dataset.done=1;let ok=b.dataset.ok==='true';b.classList.add(ok?'right':'wrong');let f=box.querySelector('.feedback');if(f){f.hidden=false;f.textContent=(ok?'Correct. ':'Try again. ')+(b.dataset.why||'')}let kind=b.dataset.kind;if(kind){let item=day()[aiSetKey(kind)]?.[+b.dataset.index],q=item?.questions?.[+b.dataset.question];if(q)rec(ok,{id:`${kind}-${levelKey()}-${b.dataset.index}-${b.dataset.question}`,q:q.stem,options:q.o,answer:q.o[q.ans],hits:0})}else rec(ok)});let stage=$('#petStageFox');if(stage)stage.onclick=()=>{stage.classList.remove('petCelebrate');void stage.getBoundingClientRect();stage.classList.add('petCelebrate')}}
function render(){if(!['dashboard','reading','listening','words','pet'].includes(tab))tab='dashboard';let view={dashboard,reading,listening,words,pet:petPage}[tab];try{app.innerHTML=view()}catch(e){console.error(e);app.innerHTML='<section class="card"><h2>载入发生问题</h2><p>请重新整理后再试。</p></section>'}document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));bind()}

/* Current-news rewrite flow: RSS provides every event-specific fact; AI only rewrites it. */
function newsKey(kind,a){return `news-${kind}-${q()}-${levelKey()}-${a.id}`}
function levelStars(){return starMeta()[levelKey()].stars}
async function ensureNews(kind){let d=day(),articles=d.rssArticles||[],idx=kind==='reading'?(d.newsReadIndex||0):(d.newsListenIndex||0),a=articles[idx];if(!a)return;let key=newsKey(kind,a);if(d[key]||d.newsLoading)return;d.newsLoading=key;render();let endpoint=kind==='reading'?'/api/news-rewrite':'/api/news-listening';let r=await api(endpoint,{article:a,difficulty:levelKey()});if(r.result)d[key]={...r.result,status:'ready',cached:r.cached};else d[key]={status:'failed',error:r.error||'未達規格',source_name:a.source,source_url:a.link,source_date:a.published};d.newsLoading='';save();render()}
function sourceLine(item){let link=item.source_url?` · <a class="sourceLink" href="${item.source_url}" target="_blank" rel="noopener">原文連結 ↗</a>`:' · 本次為 AI 生成，非即時新聞';return `<p class="newsCredit">根據 <b>${item.source_name||'RSS 來源'}</b> ${item.source_date||''} 報導改寫${link}</p>`}
function reading(){let d=day();if(!d.rssArticles){setTimeout(loadRss,0);return `<section class="card"><h2>今日閱讀</h2><p>正在載入真實 RSS 新聞來源…</p></section>`}let articles=d.rssArticles,idx=d.newsReadIndex||0,a=articles[idx],key=newsKey('reading',a),item=d[key];if(!item&&!d.newsLoading)setTimeout(()=>ensureNews('reading'),0);let isAi=Boolean(a.ai),tier=isAi?'本次為 AI 生成，非即時新聞':(d.rssTier||'RSS article pool');return `<section class="card"><div class="row"><h2 class="grow">真新聞閱讀 ${idx+1}/${articles.length}</h2>${difficulty()}<span class="qualityBadge ${isAi?'qualityWarn':''}">${tier}</span></div>${sourceHealthRows(d.rssHealth)}<span class="tag">${a.source}</span><h3>${a.title}</h3><p class="small">RSS 發布：${a.published}</p><p class="small">素材僅使用標題與摘要；AI 不會自行發明新聞事件。</p><div class="row"><button id="newsNext">換一篇</button><button class="rssSpeak">朗讀摘要</button>${a.link?`<a class="sourceLink" href="${a.link}" target="_blank" rel="noopener">RSS 原文 ↗</a>`:''}</div></section><section class="card"><h2>難度改寫文章</h2>${d.newsLoading===key?'<p>正在根據這則 RSS 報導改寫並驗證詞數、難度與來源…</p>':''}${item&&item.status==='failed'?`<p class="feedback qualityWarn">未達規格：${item.error}</p>${sourceLine(item)}`:''}${item&&item.status==='ready'?`<div class="row">${qualityBadge(item.validation)}<span class="tag">${item.cached?'今日快取':'剛完成改寫'}</span></div><p class="passage">${item.en}</p><details><summary>查看完整中文翻譯</summary><p class="translation">${item.zh}</p></details>${sourceLine(item)}<h3>閱讀測驗</h3>${item.questions.map((x,i)=>`<div class="longQ"><h3>${i+1}. ${x.stem}</h3>${x.o.map((o,j)=>`<button class="option newsAnswer" data-ok="${j===x.ans}">${'ABCD'[j]}. ${o}</button>`).join('')}<div class="feedback" hidden></div></div>`).join('')}`:''}</section>`}
function listening(){let d=day();if(!d.rssArticles){setTimeout(loadRss,0);return `<section class="card"><h2>聽力</h2><p>正在載入真新聞素材…</p></section>`}let articles=d.rssArticles,idx=d.newsListenIndex||0,a=articles[idx],key=newsKey('listening',a),item=d[key];if(!item&&!d.newsLoading)setTimeout(()=>ensureNews('listening'),0);return `<section class="card"><div class="row"><h2 class="grow">真新聞聽力 ${idx+1}/${articles.length}</h2>${difficulty()}</div><span class="tag">${a.source}</span><h3>${a.title}</h3><p class="small">RSS 發布：${a.published}</p><button id="listenNewsNext">換一則新聞</button>${d.newsLoading===key?'<p>正在依目前星等改寫與驗證聽力材料…</p>':''}${item&&item.status==='failed'?`<p class="feedback qualityWarn">未達規格：${item.error}</p>${sourceLine(item)}`:''}${item&&item.status==='ready'?`<div class="row">${qualityBadge(item.validation)}<span class="tag">${item.cached?'今日快取':'剛完成改寫'}</span></div><button id="listenSpeak">播放英文</button><p class="passage">${item.en}</p>${sourceLine(item)}${item.questions.map((x,i)=>`<div class="listenNew"><h3>${i+1}. ${x.stem}</h3>${x.o.map((o,j)=>`<button class="option newsAnswer" data-ok="${j===x.ans}">${'ABCD'[j]}. ${o}</button>`).join('')}<div class="feedback" hidden></div></div>`).join('')}`:''}</section>`}
async function loadRss(){let d=day();if(d.rssLoading||d.rssArticles)return;d.rssLoading=true;render();try{let seen=readHistory(),r=await api('/api/rss',{seen}),a=(r.articles||[]).slice(0,8);d.rssTier=r.meta&&r.meta.tier||'RSS';d.rssHealth=r.meta&&r.meta.health||{};d.rssArticles=a.length?a:fallbackRss().map(x=>({...x,ai:true}));d.communityArticles=Array.isArray(r.community)?r.community:[];saveReadHistory([...seen,...d.rssArticles.filter(x=>!x.ai).map(x=>x.id)]);d.newsReadIndex=0;d.newsListenIndex=0}catch{d.rssTier='本次為 AI 生成，非即時新聞';d.rssHealth={};d.rssArticles=fallbackRss().map(x=>({...x,ai:true}));d.communityArticles=[]}d.rssLoading=false;save();render()}
function bind(){document.querySelectorAll('[data-tab],[data-go]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab||b.dataset.go;render();window.scrollTo({top:0,behavior:'smooth'})});let brand=$('#brandHome');if(brand)brand.onclick=()=>{tab='dashboard';render()};document.querySelectorAll('.globalLevel').forEach(x=>x.onchange=()=>{set.level=x.value;saveSet();render()});document.querySelectorAll('.rssSpeak').forEach(b=>b.onclick=()=>{let a=day().rssArticles[(day().newsReadIndex||0)];speech(a.en)});let nn=$('#newsNext');if(nn)nn.onclick=()=>{let d=day();d.newsReadIndex=((d.newsReadIndex||0)+1)%d.rssArticles.length;save();render()};let ln=$('#listenNewsNext');if(ln)ln.onclick=()=>{let d=day();d.newsListenIndex=((d.newsListenIndex||0)+1)%d.rssArticles.length;save();render()};let ls=$('#listenSpeak');if(ls)ls.onclick=()=>{let d=day(),a=d.rssArticles[d.newsListenIndex||0],x=d[newsKey('listening',a)];if(x&&x.en)speech(x.en)};document.querySelectorAll('.wordSpeak').forEach(b=>b.onclick=()=>speech(b.dataset.w));document.querySelectorAll('[data-favorite]').forEach(b=>b.onclick=()=>openFavoriteEditor(b.dataset.favorite));document.querySelectorAll('[data-pane]').forEach(b=>b.onclick=()=>switchWordPane(b.dataset.pane));let f=$('#favFilter');if(f)f.onchange=()=>$('#favList').innerHTML=favRows(favoriteStore(),f.value);let rf=$('#reviewFilter');if(rf)rf.onchange=()=>{reviewCategory=rf.value;render()};document.querySelectorAll('.renameCat').forEach(b=>b.onclick=()=>renameCategory(b.dataset.cat));document.querySelectorAll('.deleteCat').forEach(b=>b.onclick=()=>deleteCategory(b.dataset.cat));document.querySelectorAll('.newsAnswer,.longAnswer,.listenNewAnswer,.vocabInline,.favAnswer,.rssAnswer').forEach(b=>b.onclick=()=>{let box=b.parentElement;if(box.dataset.done)return;box.dataset.done=1;let ok=b.dataset.ok==='true';b.classList.add(ok?'right':'wrong');let feed=box.querySelector('.feedback');if(feed){feed.hidden=false;feed.textContent=ok?'Correct!':'Keep going — review the related sentence.'}rec(ok)});let stage=$('#petStageFox');if(stage){stage.onclick=()=>{stage.classList.remove('petCelebrate');void stage.getBoundingClientRect();stage.classList.add('petCelebrate')}}}
function render(){if(!['dashboard','reading','listening','words','pet'].includes(tab))tab='dashboard';let view={dashboard,reading,listening,words,pet:petPage}[tab];try{app.innerHTML=view()}catch(e){console.error(e);app.innerHTML='<section class="card"><h2>載入發生問題</h2><p>已保留本機資料；請重新整理後再試。</p></section>'}document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));bind()}
tab='dashboard'; if(data)render();

/* Quality-layer UI: show the backend validation rather than silently accepting weak content. */
function textWords(text){return (String(text||'').match(/[A-Za-z]+(?:'[A-Za-z]+)?/g)||[]).length}
function estimateLevelText(key){return ({one:'★ B2',two:'★★ C1',three:'★★★ C1+/C2',four:'★★★★ C2'})[key]||'未評估'}
function qualityBadge(meta,fallback=false){let words=meta&&meta.word_count;return `<span class="qualityBadge ${fallback?'qualityWarn':''}">${words?`${words} 詞`:'詞數未達規格'} · ${estimateLevelText(meta&&meta.estimated_level||levelKey())}${fallback?' · 未達規格':''}</span>`}
function seedListening(){let text=`Good morning, everyone. This is Maya Chen from the regional operations office. I am calling with an update about Thursday's client workshop, which had originally been scheduled for the downtown conference center. Because the center will be repairing its ventilation system, the workshop has been moved to the Riverside Hotel, two blocks from our usual location. Registration will still begin at eight forty-five, and the first presentation will start promptly at nine fifteen. Please bring the revised project brief that was emailed yesterday, not the earlier draft. Attendees who need parking should contact the hotel directly before Wednesday afternoon, because spaces are limited. After the workshop, a short feedback survey will be sent to everyone who signed in.`;return {text,questions:[{stem:'Why was the location changed?',o:['The conference center needs repairs.','The hotel offered free rooms.','The client canceled the workshop.','The office is moving.'],ans:0,why:'The middle of the announcement explains the repair work.'},{stem:'What should attendees bring?',o:['The revised project brief.','A parking receipt.','The original draft.','A hotel reservation.'],ans:0,why:'The announcement specifies the revised brief.'},{stem:'When does the first presentation begin?',o:['At 9:15.','At 8:45.','On Wednesday afternoon.','After the survey.'],ans:0,why:'The time is stated after registration details.'},{stem:'Who should contact the hotel?',o:['People who need parking.','All speakers.','Only clients.','Survey participants.'],ans:0,why:'The final section discusses limited parking.'}]}}
async function ensureListeningQuality(){let d=day(),key=`listeningQuality-${levelKey()}`;if(d[key]||d.listeningLoading)return;d.listeningLoading=true;render();let r=await api('/api/listening',{difficulty:starMeta()[levelKey()].stars});if(r.result)d[key]={...r.result,status:'ready',validation:r.validation};else {let seed=seedListening();d[key]={...seed,status:'seed',validation:{word_count:textWords(seed.text),estimated_level:'two'},error:r.error||'AI listening unavailable'}}d.listeningLoading=false;save();render()}
function listening(){let d=day(),key=`listeningQuality-${levelKey()}`,item=d[key];if(!item&&!d.listeningLoading)setTimeout(ensureListeningQuality,0);if(!item)return `<section class="card"><h2>聽力</h2><p>正在依難度產生並驗證材料…</p></section>`;let fallback=item.status!=='ready';return `<section class="card"><div class="row"><h2 class="grow">聽力測驗</h2>${difficulty()}${qualityBadge(item.validation,fallback)}</div><p class="small">${fallback?'種子內容：AI 未達規格或暫時不可用。':'已通過 120 詞、題數與段落覆蓋驗證。'}</p><button id="listenSpeak">▶ 播放</button><p class="passage">${item.text}</p>${item.questions.map((x,i)=>`<div class="listenNew"><h3>${i+1}. ${x.stem}</h3>${x.o.map((o,j)=>`<button class="option listenNewAnswer" data-ok="${j===x.ans}">${'ABCD'[j]}. ${o}</button>`).join('')}<div class="feedback" hidden></div></div>`).join('')}</section>`}
function petPage(){let p=data.pet||{mood:65,food:0};return `<section class="card petPage"><div class="petStage"><svg id="petStageFox" class="foxSvg" viewBox="0 0 300 340" role="button" tabindex="0" aria-label="和 Foxy 互動"><g class="foxTailSvg"><path d="M221 245c62-20 68 44 21 57-31 9-54-7-70-27 22 4 36-9 49-30z" fill="#e9874d" stroke="#9d4d32" stroke-width="7"/><path d="M239 272c21-6 28 12 8 18-14 4-26-1-35-9 12 1 19-2 27-9z" fill="#fff4df"/></g><g class="foxBodySvg"><path d="M91 165c-21 34-17 112 18 135 22 15 61 15 83 0 35-23 39-101 17-135z" fill="#e9874d" stroke="#9d4d32" stroke-width="7"/><path d="M117 193c4 53 14 83 33 89 19-6 29-36 33-89-19 9-46 9-66 0z" fill="#fff4df"/></g><g class="foxHeadSvg"><path d="M81 119 73 38l57 42c13-5 28-5 41 0l56-42-8 81c9 16 11 43 3 62-12 29-52 48-102 42-39-5-65-30-66-61-1-17 3-31 8-43z" fill="#e9874d" stroke="#9d4d32" stroke-width="7" stroke-linejoin="round"/><path d="m86 60 11 42 23-17zM214 60l-11 42-23-17z" fill="#553d44"/><path d="M104 166c11 39 80 39 92 0-19 10-73 10-92 0z" fill="#fff4df"/><ellipse class="foxEye leftEye" cx="116" cy="137" rx="8" ry="11" fill="#263451"/><ellipse class="foxEye rightEye" cx="184" cy="137" rx="8" ry="11" fill="#263451"/><path d="m145 154 10 0-5 6z" fill="#263451"/></g></svg><p id="stagePetSpeech" class="stagePetSpeech">${p.lastPrompt||'今天想從哪一個英文任務開始？'}</p><p class="small">點一下 Foxy，牠會跳起來並回應你。</p></div></section><section class="card petInfo"><h2>Foxy 的狀態</h2><div class="dashboardGrid"><div class="dashMetric"><span>心情</span><b>${p.mood||65} / 100</b></div><div class="dashMetric"><span>飼料</span><b>🍪 ${p.food||0}</b></div></div><button id="openPetChat">和 Foxy 聊聊天</button></section>`}
async function loadRss(){let d=day();if(d.rssLoading||d.rssArticles)return;d.rssLoading=true;render();try{let seen=readHistory(),r=await api('/api/rss',{seen}),a=(r.articles||[]).slice(0,3);d.rssTier=r.meta&&r.meta.tier||'ai-needed';d.rssHealth=r.meta&&r.meta.health||{};d.rssArticles=a.length>=3?a:fallbackRss().map(x=>({...x,ai:true}));d.communityArticles=Array.isArray(r.community)?r.community:[];d.rssArticles.forEach(x=>x.questions=quizForArticle(x));saveReadHistory([...seen,...d.rssArticles.map(x=>x.id)]);d.rssReadIndex=0;d.rssQuizIndex=0}catch{d.rssTier='AI generated fallback';d.rssHealth={};d.rssArticles=fallbackRss().map(x=>({...x,ai:true}));d.communityArticles=[];d.rssArticles.forEach(x=>x.questions=quizForArticle(x))}d.rssLoading=false;save();render()}
function sourceHealthRows(health){let rows=Object.entries(health||{});if(!rows.length)return '<p class="small">來源健康狀態尚未建立。</p>';let body=rows.map(([name,h])=>'<p><b>'+name+'</b> · '+(h.status==='success'?'✓ 成功':'✕ 暫時不可用')+' · '+(h.count||0)+' 篇 · '+(h.ms||0)+' ms'+(h.last_success?' · 最後成功：'+h.last_success:'')+'</p>').join('');return '<details class="health"><summary>來源健康狀態</summary>'+body+'</details>'}
function reading(){let d=day();if(!d.rssArticles){setTimeout(loadRss,0);return `<section class="card"><h2>今日閱讀</h2><p>正在並行檢查新聞來源與文章池…</p></section>`}let a=d.rssArticles[d.rssReadIndex||0],qa=d.rssArticles[d.rssQuizIndex||0],key=longKey(qa),long=d[key],community=d.communityArticles||[];if(!long&&!d.longLoading)setTimeout(ensureLong,0);let tier=d.rssTier||'article pool';return `<section class="card"><div class="row"><h2 class="grow">今日閱讀 ${(d.rssReadIndex||0)+1}/${d.rssArticles.length}</h2>${difficulty()}<span class="qualityBadge">${tier}${a.cache?' · 快取文章':''}${a.ai?' · AI 生成':''}</span></div>${sourceHealthRows(d.rssHealth)}<span class="tag">${a.source}</span><h3>${a.title}</h3><p class="small">${a.published}</p><p class="passage">${a.en}</p><h3>中文翻譯</h3><p class="translation">${a.zh}</p><div class="row"><button class="rssSpeak">🔊 朗讀</button><button class="rssNext">下一篇</button>${a.link?`<a class="sourceLink" href="${a.link}" target="_blank" rel="noopener">原文連結 ↗</a>`:''}</div></section><section class="card communityCard"><h2>社群補充</h2>${community.length?community.map(x=>`<article class="communityItem"><span class="tag">${x.source}</span><a href="${x.link}" target="_blank" rel="noopener"><b>${x.title}</b></a><p class="small">u/${x.author||'unknown'} · ${x.published||''}</p></article>`).join(''):'<p class="small">暫無社群內容</p>'}</section><section class="card"><div class="row"><h2 class="grow">閱讀測驗 ${(d.rssQuizIndex||0)+1}/${d.rssArticles.length}</h2><button class="quizNext">下一篇測驗</button>${long&&long.validation?qualityBadge(long.validation):''}</div>${d.longLoading?'<p>正在一次生成、驗證 600+ 字長文與完整題組…</p>':''}${long&&long.status==='failed'?`<p class="feedback qualityWarn">未達規格：${long.error}</p>`:''}${long&&long.status==='ready'?`<p class="small">已通過詞數／難度驗證 · ${qa.title}</p><p class="passage">${long.en}</p><details><summary>查看中文翻譯</summary><p class="translation">${long.zh}</p></details>${long.questions.map((x,i)=>`<div class="longQ"><h3>${i+1}. ${x.stem}</h3>${x.o.map((o,j)=>`<button class="option longAnswer" data-ok="${j===x.ans}">${'ABCD'[j]}. ${o}</button>`).join('')}<div class="feedback" hidden></div></div>`).join('')}`:''}</section>`}
async function ensureLong(){let d=day(),a=d.rssArticles&&d.rssArticles[d.rssQuizIndex||0];if(!a)return;let key=longKey(a);if(d[key]||d.longLoading)return;d.longLoading=true;render();let r=await api('/api/longread',{article:a,difficulty:starMeta()[levelKey()].stars});if(r.result)d[key]={...r.result,status:'ready',validation:r.validation};else d[key]={status:'failed',error:r.error||'AI long-read generation is unavailable',validation:r.validation};d.longLoading=false;save();render()}
function bind(){document.querySelectorAll('[data-tab],[data-go]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab||b.dataset.go;render();window.scrollTo({top:0,behavior:'smooth'})});let brand=$('#brandHome');if(brand)brand.onclick=()=>{tab='dashboard';render()};document.querySelectorAll('.globalLevel').forEach(x=>x.onchange=()=>{set.level=x.value;saveSet();render()});document.querySelectorAll('.rssSpeak').forEach(b=>b.onclick=()=>speech(day().rssArticles[day().rssReadIndex||0].en));document.querySelectorAll('.rssNext').forEach(b=>b.onclick=()=>{let d=day();d.rssReadIndex=((d.rssReadIndex||0)+1)%d.rssArticles.length;save();render()});document.querySelectorAll('.quizNext').forEach(b=>b.onclick=()=>{let d=day();d.rssQuizIndex=((d.rssQuizIndex||0)+1)%d.rssArticles.length;save();render()});document.querySelectorAll('.wordSpeak').forEach(b=>b.onclick=()=>speech(b.dataset.w));document.querySelectorAll('[data-favorite]').forEach(b=>b.onclick=()=>openFavoriteEditor(b.dataset.favorite));document.querySelectorAll('[data-pane]').forEach(b=>b.onclick=()=>switchWordPane(b.dataset.pane));let f=$('#favFilter');if(f)f.onchange=()=>$('#favList').innerHTML=favRows(favoriteStore(),f.value);let rf=$('#reviewFilter');if(rf)rf.onchange=()=>{reviewCategory=rf.value;render()};document.querySelectorAll('.renameCat').forEach(b=>b.onclick=()=>renameCategory(b.dataset.cat));document.querySelectorAll('.deleteCat').forEach(b=>b.onclick=()=>deleteCategory(b.dataset.cat));document.querySelectorAll('.longAnswer,.listenNewAnswer,.vocabInline,.favAnswer,.rssAnswer').forEach(b=>b.onclick=()=>{let box=b.parentElement;if(box.dataset.done)return;box.dataset.done=1;let ok=b.dataset.ok==='true';b.classList.add(ok?'right':'wrong');let feed=box.querySelector('.feedback');if(feed){feed.hidden=false;feed.textContent=ok?'Correct!':'Keep going — review the related sentence.'}rec(ok)});let ls=$('#listenSpeak');if(ls)ls.onclick=()=>speech(document.querySelector('.passage').textContent);let stage=$('#petStageFox');if(stage){let react=()=>{stage.classList.remove('petCelebrate');void stage.getBoundingClientRect();stage.classList.add('petCelebrate');let t=['尾巴收到你的招呼！','你回來了，我們一起練英文。','今天的一小題，也算進步。'];$('#stagePetSpeech').textContent=t[Math.floor(Math.random()*t.length)];let h=$('#hearts');if(h){h.textContent='♥';h.classList.add('petHeart');setTimeout(()=>{h.textContent='';h.classList.remove('petHeart')},1000)}};stage.onclick=react;stage.onkeydown=e=>{if(e.key==='Enter'||e.key===' ')react()}}let chat=$('#openPetChat');if(chat)chat.onclick=()=>{$('#chat').hidden=false;showChat()}}
function render(){if(!['dashboard','reading','listening','words','pet'].includes(tab))tab='dashboard';let view={dashboard,reading,listening,words,pet:petPage}[tab];try{app.innerHTML=view()}catch(e){console.error(e);app.innerHTML='<section class="card"><h2>載入發生問題</h2><p>已保留本機資料；請重新整理後再試。</p></section>'}document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));bind()}
/* Runtime rollback for the final daily-AI experiment. This runs after legacy declarations load. */
setTimeout(()=>{favoriteStore=()=>{try{return JSON.parse(localStorage.getItem('bright-favorites-v1')||'[]')}catch{return []}};saveFavorites=items=>localStorage.setItem('bright-favorites-v1',JSON.stringify(items));dashboard=()=>{let d=day(),p=taskProgress()*20;return `<section class="card hero"><div><p class="quote">Small steps, bright results.</p><h1>Today with Foxy</h1><div class="progress"><b style="width:${p}%"></b></div><p class="small">Daily completion: ${p}%</p></div><div class="mascot">🦊</div></section><section class="card"><h2>Daily tasks</h2>${[['reading','Reading'],['listening','Listening'],['words','Daily words']].map(x=>`<div class="task"><b>${x[1]}</b><button data-go="${x[0]}">Open</button></div>`).join('')}</section>`};words=()=>{let d=day(),m=starMeta()[levelKey()],pool=pools[m.pool];if(!d.words||!d.words.length||d.wordLevel!==levelKey()){d.words=pool.slice().sort(()=>Math.random()-.5).slice(0,15);d.wordLevel=levelKey();save()}let favs=favoriteStore(),cats=['All',...new Set(favs.map(x=>x.category))],quiz=d.words.slice(0,5);return `<section class="card"><div class="row"><h2 class="grow">Words · ${m.stars}</h2>${difficulty()}</div><div class="subtabs"><button data-pane="learn">Today’s words</button><button data-pane="quiz">Vocabulary quiz</button><button data-pane="favorites">My favorites (${favs.length})</button><button data-pane="review">Favorite review</button></div><div class="wordSection" data-section="learn">${favPanel(d.words)}</div><div class="wordSection" data-section="quiz" hidden>${quiz.map(w=>`<article class="word"><h3>${w}</h3></article>`).join('')}</div><div class="wordSection" data-section="favorites" hidden><label>Category <select id="favFilter" class="input">${cats.map(c=>`<option>${c}</option>`).join('')}</select></label><div id="favList">${favRows(favs)}</div></div><div class="wordSection" data-section="review" hidden>${favoriteReview()}</div></section>`};if(data)render()},0);
